[85811] = {id=85811,name="Thrayir, Eyes of the Siren",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=10416,mapID=2369,description="Thrayir, Eyes of the Siren . He awaits your acceptance.>",questType="standard"},
[85815] = {id=85815,name="A Small Pouch of Crystals",level=70,requiredLevel=70,faction="both",expansion=11,zoneID=15347,mapID=2346,starts={{npcID=231409,x=0.436,y=0.508,mapID=2346}},ends={{npcID=231409,x=0.436,y=0.508,mapID=2346}},coords={x=0.436,y=0.508,source="quest_giver",mapID=2346},questType="standard"},
[85818] = {id=85818,name="A Small Pouch of Crystals",level=70,requiredLevel=70,faction="both",expansion=11,zoneID=15347,mapID=2346,starts={{npcID=231409,x=0.436,y=0.508,mapID=2346}},ends={{npcID=231409,x=0.436,y=0.508,mapID=2346}},coords={x=0.436,y=0.508,source="quest_giver",mapID=2346},questType="standard"},
[86625] = {id=86625,name="The Clue in the Inn",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,description="Call me paranoid, you'd be correct, but I have been chased out of enough towns that I have a system. I establish a safehouse. Somewhere easily defensible, with enough materials that I can finish any delicate tasks and prepare for departure. That is the situation we find ourselves in-- we will retreat to the top floor of the inn and assess our options from there. I had shared the location with Caliea, when she was still studying with me... hopefully it serves us better than it did her.",questType="standard"},
[86996] = {id=86996,name="Dark Places",level=88,requiredLevel=88,faction="none",expansion=11,zoneID=15458,mapID=2405,questType="standard"},
[87350] = {id=87350,name="Abundance: Loaknit Den",level=80,requiredLevel=80,faction="none",expansion=11,questType="standard"},
[88926] = {id=88926,name="Return to Belanaar",level=90,requiredLevel=90,faction="none",expansion=11,description="This has been most productive. I suspected the kaldorei might be our the most difficult to convince, but Shandris has turned a new leaf of leadership for her people. Let this be the first of many successful partnerships between our people. Now swiftly, . Let us return home and prepare our defense.",questType="standard"},
[88932] = {id=88932,name="With the Shal'dorei",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=7637,mapID=680,description="Our reinforcements will be arriving shortly. Some will stay behind to defend Suramar. The rest will join us in Silvermoon. Thank you for joining me in this journey, . Hold on to the memory of this place in the battles to come. It will shield you from any doubt the void plants within you. Accompany me back to Silvermoon. We have many allies to find yet if we are to prevail against this force.",questType="standard"},
[88982] = {id=88982,name="Prey Contract: Renegade Magister",level=90,requiredLevel=90,faction="none",expansion=11,questType="standard"},
[89285] = {id=89285,name="Saltheril's Favor",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,questType="standard"},
[89307] = {id=89307,name="Saltheril's Favor",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,questType="standard"},
[89311] = {id=89311,name="Saltheril's Favor",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,questType="standard"},
[89314] = {id=89314,name="Saltheril's Favor",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,questType="standard"},
[89385] = {id=89385,name="First Step Into Parenthood",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15968,mapID=2395,starts={{npcID=241553,x=0.568,y=0.356,mapID=2395}},ends={{npcID=241553,x=0.568,y=0.356,mapID=2395}},coords={x=0.568,y=0.356,source="quest_giver",mapID=2395},questType="standard"},
[89409] = {id=89409,name="Infinite Bronze",level=10,requiredLevel=10,faction="both",expansion=11,zoneID=7502,mapID=627,description="Now that we have the stabilizing materials and the frayed threads we can get to work. I am, however, forbidden from directly interacting with this timeline. So, you'll need to be my hands. Not to worry, nothing forbids me from giving you some guidance. Head next door to the forge inside Tanks for Everything and we'll get to work.",questType="standard"},
[90093] = {id=90093,name="Prey Contract: Murloc Shadowhunter",level=90,requiredLevel=90,faction="none",expansion=11,questType="standard"},
[90536] = {id=90536,name="The Tale of Wey'nan's Ward",level=83,requiredLevel=83,faction="none",expansion=11,zoneID=15355,mapID=2413,questType="standard"},
[90538] = {id=90538,name="Prey Contract: Zealous Crusader",level=90,requiredLevel=90,faction="none",expansion=11,questType="standard"},
[90746] = {id=90746,name="The Elves Assemble",level=90,requiredLevel=90,faction="none",expansion=11,description="The time for preparations have passed. Xal'atath's forces are upon us. Join us, champion, as we must rebuff this assault and then press our attack on the Darkwell.",questType="standard"},
[90889] = {id=90889,name="Tale of the Echoes of Sai'alyo",level=83,requiredLevel=83,faction="none",expansion=11,zoneID=15355,mapID=2413,questType="standard"},
[90943] = {id=90943,name="Stormarion Assault",level=90,requiredLevel=90,faction="none",expansion=11,questType="standard"},
[90993] = {id=90993,name="Take the Darkwell!",level=90,requiredLevel=90,faction="none",expansion=11,description="We have our army but what lies behind these walls are the most powerful, most vile, and most empowered foes Xal'atath has in her arsenal. Gather your strongest allies, , and meet us within. It is time to end this and take back our well.",questType="raid"},
[91095] = {id=91095,name="Prey: Magister Sunbreaker (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms. I see something of myself in him. Kill it for me.",questType="standard"},
[91096] = {id=91096,name="Prey: Magistrix Emberlash (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends... She has burned one too many mutual acquaintances. If she will not control her power, we will gladly take it for our own.",questType="standard"},
[91097] = {id=91097,name="Prey: Senior Tinker Ozwold (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others. His ambition is admirable, but his methods are irredeemable. Go and see that his inventing days come to an end.",questType="standard"},
[91098] = {id=91098,name="Prey: L-N-0R the Recycler (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Do you know why they call her the Recycler, $p? I don't. And given her history of \"disappearing\" shop assistants, I'm not really inclined to ask her. That being said, watch your step. I understand that she likes to incorporate her victims into her gadgetry. We wouldn't want you becoming a pocket watch or some such thing.",questType="standard"},
[91099] = {id=91099,name="Prey: Mordril Shadowfell (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="The Void is a perfidious thing, like water. The wise keep it at a respectful distance, never dancing too close to the edge. The foolish dive in, and in so doing, drown. Mordril is a danger to himself and everyone around him, so lost is he in his own obsession. See to it that he no longer poses a threat to this realm.",questType="standard"},
[91100] = {id=91100,name="Prey: Deliah Gloomsong (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="In a previous life, Deliah Gloomsong was a prodigious student--truly a marvel of ambition, talent, and unrelenting curiosity. It was the latter that got the best of her. Put an end to her murderous spree.",questType="standard"},
[91101] = {id=91101,name="Prey: Phaseblade Talasha (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Ethereals... they make my skin crawl. Esoteric. Unknowable. I don't trust anything I can't look in the eyes while it grovels before me. My scouts report that a particularly dangerous ethereal is active in a nearby region. We would do well to nip this in the bud while we still can.",questType="standard"},
[91102] = {id=91102,name="Prey: Nexus-Edge Hadim (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Our activities are drawing unwanted attention. I have heard whispers that a powerful ethereal assassin is on my... on our trail. It would be very difficult indeed to defend our city as twin piles of bloody ribbons. Go out there and show this \"assassin\" the true art of the kill.",questType="standard"},
[91103] = {id=91103,name="Prey: Jo'zolo the Breaker (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Jo'zolo the Breaker is a troll who abides by his name. Long has he been the bane of our scouts, but no more! Kill him. Feed his anguish to the defenses of our beloved city.",questType="standard"},
[91104] = {id=91104,name="Prey: Zadu, Fist of Nalorakk (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with. There is one named Zadu. Her anguish would make for a most excellent trophy...",questType="standard"},
[91105] = {id=91105,name="Prey: The Talon of Jan'alai (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake. See to it that he joins the spirits he so ardently venerates.",questType="standard"},
[91106] = {id=91106,name="Prey: The Wing of Akil'zon (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her. Oh, and be careful. She's responsible for more than one lost Farstrider patrol.",questType="standard"},
[91107] = {id=91107,name="Prey: Ranger Swiftglade (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people. End his sadistic killing spree and put his anguish to better use.",questType="standard"},
[91108] = {id=91108,name="Prey: Lieutenant Blazewing (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. Whether this is possession or sedition I am unsure, but she must be dealt with.",questType="standard"},
[91109] = {id=91109,name="Prey: Petyoll the Razorleaf (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. Hunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.",questType="standard"},
[91110] = {id=91110,name="Prey: Lamyne of the Undercroft (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Do you garden, $p? I've been known to dabble. It seems the plants in our realm are becoming somewhat overbearing these days, sprouting legs and arms and running around murdering our brave soldiers. Let's give them a bit of a pruning, shall we?",questType="standard"},
[91111] = {id=91111,name="Prey: High Vindicator Vureem (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it. In the absence of total purity, Vureem sees only violence and the shadows of his own dogma. What say we put his worldview to the test?",questType="standard"},
[91112] = {id=91112,name="Prey: Crusader Luxia Maxwell (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="We are not sure if Luxia Maxwell is a deserter or has simply decided to embark on her own personal crusade. Regardless, reports are coming in of her attacking both friend and foe alike, yelling aphorisms of purity and duty. She has become a liability to the defense of Silvermoon. Go and harvest her anguish.",questType="standard"},
[91113] = {id=91113,name="Prey: Praetor Singularis (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="The domanaar... I do not profess to know much about them, other than their proclivity for subterfuge, guile, and the absolute destruction of anything that stands before them. Praetor Singularis is no exception. They have been confounding our forces at every turn. Go and put an end to their games.",questType="standard"},
[91114] = {id=91114,name="Prey: Consul Nebulor (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="I have heard that there is one under Xal'atath's command who takes particular delight in dominating their foes. Whispers of a domanaar that taunts its victims with whispers and riddles before annihilating their mortal coil with void magic. Consul Nebulor is their name. Go and show them the limits of their power.",questType="standard"},
[91115] = {id=91115,name="Prey: Executor Kaenius (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will. Executor Kaenius is one such domanaar. They stalk the battlefield, singling out our strongest soldiers and viciously cutting them down. Put an end to their rampage.",questType="standard"},
[91116] = {id=91116,name="Prey: Imperator Enigmalia (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they. Go and avenge our fallen soldiers.",questType="standard"},
[91118] = {id=91118,name="Prey: Vylenna the Defector (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her. Then her dereliction turned violent. A veritable font of anguish if you ask me...",questType="standard"},
[91119] = {id=91119,name="Prey: Lost Theldrin (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has. He accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess... See to it that he never harms another elf again.",questType="standard"},
[91120] = {id=91120,name="Prey: Neydra the Starving (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people... And now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slake her unquenchable thirst. It's funny, the paths life takes us...",questType="standard"},
[91121] = {id=91121,name="Prey: Thornspeaker Edgath (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground. It is time we clip this thorn.",questType="standard"},
[91122] = {id=91122,name="Prey: Thorn-Witch Liset (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm. I despise the natural realm.",questType="standard"},
[91123] = {id=91123,name="Prey: Grothoz, the Burning Shadow (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. As his stupidity prevents him from using his whole brain, let us unlock his potential for him...",questType="standard"},
[91124] = {id=91124,name="Prey: Dengzag, the Darkened Blaze (Normal)",level=80,requiredLevel=80,faction="none",expansion=11,description="Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. I, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. Get to it.",questType="standard"},
[91210] = {id=91210,name="Prey: Magister Sunbreaker (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms. I see something of myself in him. Kill it for me.",questType="standard"},
[91211] = {id=91211,name="Prey: Magister Sunbreaker (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,description="Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms. I see something of myself in him. Kill it for me.",questType="standard"},
