[91230] = {id=91230,name="Prey: The Talon of Jan'alai (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake. See to it that he joins the spirits he so ardently venerates.",questType="standard"},
[91231] = {id=91231,name="Prey: The Talon of Jan'alai (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,description="There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake. See to it that he joins the spirits he so ardently venerates.",questType="standard"},
[91232] = {id=91232,name="Prey: The Wing of Akil'zon (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her. Oh, and be careful. She's responsible for more than one lost Farstrider patrol.",questType="standard"},
[91233] = {id=91233,name="Prey: The Wing of Akil'zon (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,description="Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her. Oh, and be careful. She's responsible for more than one lost Farstrider patrol.",questType="standard"},
[91234] = {id=91234,name="Prey: Ranger Swiftglade (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people. End his sadistic killing spree and put his anguish to better use.",questType="standard"},
[91235] = {id=91235,name="Prey: Ranger Swiftglade (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,description="It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people. End his sadistic killing spree and put his anguish to better use.",questType="standard"},
[91236] = {id=91236,name="Prey: Lieutenant Blazewing (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. Whether this is possession or sedition I am unsure, but she must be dealt with.",questType="standard"},
[91237] = {id=91237,name="Prey: Lieutenant Blazewing (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,description="I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. Whether this is possession or sedition I am unsure, but she must be dealt with.",questType="standard"},
[91238] = {id=91238,name="Prey: Petyoll the Razorleaf (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. Hunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.",questType="standard"},
[91239] = {id=91239,name="Prey: Petyoll the Razorleaf (Nightmare)",level=90,requiredLevel=90,faction="horde",expansion=11,zoneID=15969,mapID=2393,description="Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. Hunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.",ends={{npcID=246231,x=0.566,y=0.654,mapID=2393}},questType="standard"},
[91240] = {id=91240,name="Prey: Lamyne of the Undercroft (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="Do you garden, $p? I've been known to dabble. It seems the plants in our realm are becoming somewhat overbearing these days, sprouting legs and arms and running around murdering our brave soldiers. Let's give them a bit of a pruning, shall we?",questType="standard"},
[91241] = {id=91241,name="Prey: Lamyne of the Undercroft (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,description="Do you garden, $p? I've been known to dabble. It seems the plants in our realm are becoming somewhat overbearing these days, sprouting legs and arms and running around murdering our brave soldiers. Let's give them a bit of a pruning, shall we?",questType="standard"},
[91242] = {id=91242,name="Prey: High Vindicator Vureem (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it. In the absence of total purity, Vureem sees only violence and the shadows of his own dogma. What say we put his worldview to the test?",questType="standard"},
[91243] = {id=91243,name="Prey: Crusader Luxia Maxwell (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="We are not sure if Luxia Maxwell is a deserter or has simply decided to embark on her own personal crusade. Regardless, reports are coming in of her attacking both friend and foe alike, yelling aphorisms of purity and duty. She has become a liability to the defense of Silvermoon. Go and harvest her anguish.",questType="standard"},
[91244] = {id=91244,name="Prey: Praetor Singularis (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="The domanaar... I do not profess to know much about them, other than their proclivity for subterfuge, guile, and the absolute destruction of anything that stands before them. Praetor Singularis is no exception. They have been confounding our forces at every turn. Go and put an end to their games.",questType="standard"},
[91245] = {id=91245,name="Prey: Consul Nebulor (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="I have heard that there is one under Xal'atath's command who takes particular delight in dominating their foes. Whispers of a domanaar that taunts its victims with whispers and riddles before annihilating their mortal coil with void magic. Consul Nebulor is their name. Go and show them the limits of their power.",questType="standard"},
[91246] = {id=91246,name="Prey: Executor Kaenius (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will. Executor Kaenius is one such domanaar. They stalk the battlefield, singling out our strongest soldiers and viciously cutting them down. Put an end to their rampage.",questType="standard"},
[91247] = {id=91247,name="Prey: Imperator Enigmalia (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they. Go and avenge our fallen soldiers.",questType="standard"},
[91248] = {id=91248,name="Prey: Knight-Errant Bloodshatter (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue. He is starting to become a liability. Recoup his anguish so that we can make the best of such an unfortunate situation.",questType="standard"},
[91249] = {id=91249,name="Prey: Vylenna the Defector (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her. Then her dereliction turned violent. A veritable font of anguish if you ask me...",questType="standard"},
[91250] = {id=91250,name="Prey: Lost Theldrin (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has. He accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess... See to it that he never harms another elf again.",questType="standard"},
[91251] = {id=91251,name="Prey: Neydra the Starving (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people... And now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slake her unquenchable thirst. It's funny, the paths life takes us...",questType="standard"},
[91252] = {id=91252,name="Prey: Thornspeaker Edgath (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground. It is time we clip this thorn.",questType="standard"},
[91253] = {id=91253,name="Prey: Thorn-Witch Liset (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm. I despise the natural realm.",questType="standard"},
[91254] = {id=91254,name="Prey: Grothoz, the Burning Shadow (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. As his stupidity prevents him from using his whole brain, let us unlock his potential for him...",questType="standard"},
[91255] = {id=91255,name="Prey: Dengzag, the Darkened Blaze (Hard)",level=90,requiredLevel=90,faction="none",expansion=11,description="Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. I, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. Get to it.",questType="standard"},
[91256] = {id=91256,name="Prey: High Vindicator Vureem (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,description="High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it. In the absence of total purity, Vureem sees only violence and the shadows of his own dogma. What say we put his worldview to the test?",questType="standard"},
