[91465] = {id=91465,name="Stormarion Assault",level=90,requiredLevel=90,faction="none",expansion=11,questType="standard"},
[91475] = {id=91475,name="Abundance: Abundant Voidburrow",level=80,requiredLevel=80,faction="none",expansion=11,questType="standard"},
[91739] = {id=91739,name="Endeavor Reward",level=25,requiredLevel=25,faction="none",expansion=11,questType="standard"},
[91834] = {id=91834,name="Guardians Must Go",level=83,requiredLevel=83,faction="none",expansion=11,questType="standard"},
[91837] = {id=91837,name="Bring Back De Bones",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15947,mapID=2437,description="Big thanks for breakin' us free. Some were not so lucky. Bring dey bones back to de Chief, he will know what to do.",questType="standard"},
[91966] = {id=91966,name="Saltheril's Soiree",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,questType="standard"},
[92319] = {id=92319,name="A Favor to Axe",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=3483,mapID=100,description="Kurdran and I spent twenty years in Outland on the other side of the Dark Portal, after we'd pushed the Horde back with Khadgar, Turalyon, and Alleria. There were some good times, but any day I don't wake up in Honor Hold is already a good day. That whole time, Kurdran led our scouts with his gryphon, Sky'ree. And on his way out of Honor Hold, he would fly low and fast, dodging everything the orcs threw at him. I think it'd be hilarious if you could go find him some mementos!",starts={{npcID=250415,x=0.472,y=0.586,mapID=2541}},ends={{npcID=250399,x=0.47,y=0.592,mapID=2541}},coords={x=0.472,y=0.586,source="quest_giver",mapID=100},questType="standard"},
[92321] = {id=92321,name="A Frostbitten Tally",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=10473,mapID=2541,description="Tarenar and I heard stories about the invasion of Icecrown Citadel from all the way out in the Plaguelands. But he's got it all wrong! The elf thinks there were more Ebon Blade commanders than Argent Crusade in the Ashen Verdict. He's completely daft. Obviously there were more paladins! Would you go poke around Icecrown Citadel and find me some proof? I'm sick of arguing with him!",starts={{npcID=250402,x=0.392,y=0.556,mapID=2541}},ends={{npcID=250402,x=0.392,y=0.556,mapID=2541}},coords={x=0.392,y=0.556,source="quest_giver",mapID=2541},questType="standard"},
[92322] = {id=92322,name="Timear Foresees a Proof of Demise!",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=6622,description="Hello, . Do you have a moment? There's something important I lost during the assault on the Isle of Thunder: a pocket watch gifted to me by my old friend, Archmage Timear. Yes, that Timear... the one that can foresee the future. He told me this day would come and that you would assist me. The watch was taken by the Council of Elders, specifically by High Priestess Mar'li. If you would go to the island and retrieve it from the Throne of Thunder, and we both know you will, I can get you there.",starts={{npcID=264499,x=0.282,y=0.198,mapID=2541}},ends={{npcID=264499,x=0.282,y=0.198,mapID=2541}},coords={x=0.282,y=0.198,source="quest_giver",zoneID=10473},questType="standard"},
[92323] = {id=92323,name="Where the Fire Once Burned",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=10473,mapID=2541,description="Hard to believe, isn't it? Horde and Alliance, same room, no stabbing. I was reminiscing about my days in the Firelands, gathering luciferns . They had such a distinctive smell... somewhere between smoke and something long dead. It's been a while, and I almost miss it. Grab a few for Zen'tabra and me, will you? She deserves the full experience.",starts={{npcID=250405,x=0.754,y=0.42,mapID=2541}},ends={{npcID=250405,x=0.754,y=0.42,mapID=2541}},coords={x=0.754,y=0.42,source="quest_giver",mapID=2541},questType="standard"},
[92324] = {id=92324,name="Uncrowned's Cold Case",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=10473,mapID=2541,description="We are lucky the Uncrowned survived, and its archives, thanks to Taoshi. We've been reading them... Have you heard of the great highborne city Dire Maul? The Uncrowned kept tabs on the dangerous prince, Tortheldrin, but since he died, the case was shelved. These notes say there might be objects of interest in the city ruins, with a notable mention of Nostro's Compendium of Dragon Slaying. That book was retrieved some time ago, but few know that several chapters were missing. Let's reopen the case.",starts={{npcID=250408,x=0.772,y=0.584,mapID=2541}},ends={{npcID=250408,x=0.772,y=0.584,mapID=2541}},coords={x=0.772,y=0.584,source="quest_giver",mapID=2541},questType="standard"},
[92325] = {id=92325,name="Hellscream's Heritage",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=3518,mapID=107,description="My sister Krenna was once a Conqueror in the Horde's armies. Ruthless. Brutal. Some said a tyrant. But she was different when we were young. Scared, but always kind to me. Warm to those she would let in. Did power change her? And if it changed her into a tyrant, did it change Garrosh Hellscream as well? I know who Krenna was. I do not know who Garrosh was. Travel to Nagrand and find out.",starts={{npcID=250410,x=0.69,y=0.568,mapID=2541}},ends={{npcID=250410,x=0.69,y=0.568,mapID=2541}},coords={x=0.69,y=0.568,source="quest_giver",mapID=107},questType="standard"},
[92326] = {id=92326,name="The Fragrance of the Dunes",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=10473,mapID=2541,description="I miss the smell of the desert. It is the fragrance of freedom in a wild land. I would love to refresh that scent memory. While you're there, grab something from the caravans. This place could use some nomad personality. Maybe hop over to Shatterstone Harbor and get something for the big guy. Maybe an anchor? That would be perfect! Imagine watching him lug that around.",starts={{npcID=250411,x=0.4,y=0.776,mapID=2541}},ends={{npcID=250411,x=0.4,y=0.776,mapID=2541}},coords={x=0.4,y=0.776,source="quest_giver",mapID=2541},questType="standard"},
[92327] = {id=92327,name="A Generational Moment",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=4706,mapID=217,description="It's always good to see someone with your history continue to speak to us old dogs, $p. Eitrigg and I have been talking about legacy recently. Did you know we both fought with the Valarjar against the Legion? Interesting how long histories can intertwine. But our real legacy is our children. I wonder if you would have time to check in with them both. While you're there, make sure they're keeping their skills sharp.",starts={{npcID=250413,x=0.524,y=0.56,mapID=2541}},ends={{npcID=250413,x=0.524,y=0.56,mapID=2541}},coords={x=0.524,y=0.56,source="quest_giver",mapID=217},questType="standard"},
[92386] = {id=92386,name="A Handful of Voidlight Marl",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,starts={{npcID=240279,x=0.458,y=0.658,mapID=2437}},ends={{npcID=240279,x=0.458,y=0.658,mapID=2437}},coords={x=0.458,y=0.658,source="quest_giver",mapID=2437},questType="standard"},
[92387] = {id=92387,name="A Cluster of Voidlight Marl",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,starts={{npcID=240279,x=0.458,y=0.658,mapID=2437}},ends={{npcID=240279,x=0.458,y=0.658,mapID=2437}},coords={x=0.458,y=0.658,source="quest_giver",mapID=2437},questType="standard"},
[92388] = {id=92388,name="A Trove of Voidlight Marl",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15947,mapID=2437,starts={{npcID=240279,x=0.458,y=0.658,mapID=2437}},ends={{npcID=240279,x=0.458,y=0.658,mapID=2437}},coords={x=0.458,y=0.658,source="quest_giver",mapID=2437},questType="standard"},
[92402] = {id=92402,name="Magical Touch",level=25,requiredLevel=25,faction="both",expansion=11,zoneID=16105,mapID=2352,description="Oh hey, just the person I was looking for! Some of your neighbors are looking to get into enchanting. They aren't quite ready for prime time yet, but I have an idea to get them started. It looks like there's an area in your neighborhood that has slight magical energy. Can you take this locator and find some crystals for them? They only need to be slightly magical. We don't want them to cause an accident!",starts={{npcID=254536,x=0.544,y=0.56,mapID=2351},{npcID=254536,x=0.52,y=0.38,mapID=2352}},ends={{npcID=254536,x=0.544,y=0.56,mapID=2351},{npcID=254536,x=0.52,y=0.38,mapID=2352}},coords={x=0.544,y=0.56,source="quest_giver",mapID=2352},questType="standard"},
[92410] = {id=92410,name="Renowned with the Magisters",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,description="The Magisters owe you a great debt. Speak with me at Saltheril's Haven. You will be duly compensated for your aid.",questType="standard"},
[92411] = {id=92411,name="Renowned with the Blood Knights",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,description="The Blood Knights owe you a great debt. Speak with me at Saltheril's Haven. You will be duly compensated for your aid.",questType="standard"},
[92412] = {id=92412,name="Renowned with the Farstriders",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,description="The Farstriders owe you a great debt. Speak with me at Saltheril's Haven. You will be duly compensated for your aid.",questType="standard"},
[92413] = {id=92413,name="Renowned with the Shades of the Row",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15968,mapID=2395,description="The Row owes you a great debt. Speak with me at Saltheril's Haven. You will be duly compensated for your aid.",questType="standard"},
[92417] = {id=92417,name="Farm to Table",level=25,requiredLevel=25,faction="both",expansion=11,zoneID=16105,mapID=2352,description="Hey, it's ! I'm in a bit of a pickle here. I'm making food for everyone, but underestimated how many people would turn up! I can whip up a quick stew and the local farmers said I could use their produce, but the other dishes are at a vital point, I can't leave them unattended! Could you gather some ripe ingredients, and bring them back?",starts={{npcID=250970,x=0.548,y=0.572,mapID=2351},{npcID=250970,x=0.53,y=0.38,mapID=2352}},ends={{npcID=250970,x=0.548,y=0.572,mapID=2351},{npcID=250970,x=0.53,y=0.38,mapID=2352}},coords={x=0.548,y=0.572,source="quest_giver",mapID=2352},questType="standard"},
[92418] = {id=92418,name="Abundance",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15947,mapID=2437,questType="standard"},
[92429] = {id=92429,name="Alternative Skinning",level=25,requiredLevel=25,faction="both",expansion=11,zoneID=16105,mapID=2352,description="Hey there! I'm working on a new method for making leather, but without harming animals. I just need small samples, fur, saliva, that sort of thing. Nothing invasive. I have this handy device that should help out!",starts={{npcID=251056,x=0.544,y=0.576,mapID=2351},{npcID=251056,x=0.528,y=0.39,mapID=2352}},ends={{npcID=251056,x=0.544,y=0.576,mapID=2351},{npcID=251056,x=0.528,y=0.39,mapID=2352}},coords={x=0.544,y=0.576,source="quest_giver",mapID=2352},questType="standard"},
[92443] = {id=92443,name="Reverse Herb Farming",level=25,requiredLevel=25,faction="both",expansion=11,zoneID=16105,mapID=2352,description="Hey there, I was collecting herbs around your neighborhood, and I kind of zoned out, and lost track of time. It's so pretty here! I think I may have picked too many herbs. I have an enchanted watering can that should help new ones grow back in, if you have the time to help them grow back?",starts={{npcID=254255,x=0.542,y=0.56,mapID=2351},{npcID=254255,x=0.528,y=0.376,mapID=2352}},ends={{npcID=254255,x=0.542,y=0.56,mapID=2351},{npcID=254255,x=0.528,y=0.376,mapID=2352}},coords={x=0.542,y=0.56,source="quest_giver",mapID=2352},questType="standard"},
[92445] = {id=92445,name="Smelting for Two",level=25,requiredLevel=25,faction="both",expansion=11,zoneID=16105,mapID=2352,description="People keep coming up to me and asking me about mining, I'm not a miner, I'm a smelter! I'm looking to teach some people about smelting, but I've been struggling with getting a crowd. Could you help me out while I talk you through smelting?",starts={{npcID=251185,x=0.54,y=0.57,mapID=2351},{npcID=251185,x=0.524,y=0.384,mapID=2352}},ends={{npcID=251185,x=0.54,y=0.57,mapID=2351},{npcID=251185,x=0.524,y=0.384,mapID=2352}},coords={x=0.54,y=0.57,source="quest_giver",mapID=2352},questType="standard"},
[92503] = {id=92503,name="Ignite the Skies: Northern Eastern Kingdoms",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=47,mapID=26,description="Have you heard the tale of the wildsages and their summer star? No? Well, you're in for quite the treat! This story will take you on a journey that follows the path the Wildhammer elders once travelled many moons ago. Take to the skies and ignite the blossom lights as I tell the tale. Our journey begins here in the hills of Loch Modan...",starts={{npcID=252784,x=0.538,y=0.692,mapID=48},{npcID=252784,x=0.192,y=0.482,mapID=26}},ends={{npcID=252784,x=0.538,y=0.692,mapID=48},{npcID=252784,x=0.192,y=0.482,mapID=26}},coords={x=0.538,y=0.692,source="quest_giver",mapID=26},questType="standard"},
