[92600] = {id=92600,name="Cracked Keystone",level=80,requiredLevel=80,faction="none",expansion=11,description="Fragmentary images of heroic deeds flash though your mind as you touch the stone, but they fade as fast as they arrive. Perhaps performing a suitably impressive task will stabilize the stone's magic once more?",questType="standard"},
[92635] = {id=92635,name="Midsummer's Journey to the Barrens",level=0,requiredLevel=0,faction="alliance",expansion=11,zoneID=17,mapID=10,description="Although we have our own traditions during this time, we are not the only ones who pay respects to the spirits of fire during the summer months. If you wish to hear the origins of the tauren traditions, travel to Kalimdor to continue your journey.",starts={{npcID=252784,x=0.538,y=0.692,mapID=48},{npcID=252784,x=0.192,y=0.482,mapID=26}},ends={{npcID=265658,x=0.624,y=0.116,mapID=10}},coords={x=0.538,y=0.692,source="quest_giver",mapID=10},questType="standard"},
[92692] = {id=92692,name="Hero's Call: Test!",level=20,requiredLevel=20,faction="alliance",expansion=11,zoneID=6662,mapID=535,description="All able-bodied citizens of the Alliance are to report to Foreman Eksos in Talador . The Iron Horde seek to control Talador . The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance. Foreman Eksos is currently establishing an outpost in Talador . Travel there and stop the Iron Horde. Glory to the Alliance!",questType="standard"},
