[93420] = {id=93420,name="Lor'themar's Judgement",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=15969,mapID=2393,description="We need to tell Lor'themar what happened here. Meet me in Silvermoon. As for Zul'jarra... she needs time. She needs her people, and her people need her. She will survive this. I am sure of it. She must!",questType="standard"},
[93495] = {id=93495,name="A Soaring Journey Through Time",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=13862,mapID=2112,description="The sands of time flow back and forth like ocean waves. Journey once more through the timeways, to the time of Dragon Aspects and Primal Incarnates. Bring me tales of victory in an era of great adventure and danger.",ends={{npcID=255019,x=0.814,y=0.47,mapID=2112}},questType="standard"},
