[93586] = {id=93586,name="Conditional - Multiple Objectives, Non Sequenced",level=83,requiredLevel=83,faction="none",expansion=11,zoneID=14998,description="I be sent out here ta prove dat I can be an amani warrior. Dis trial needs me ta collect as many trophies from dese gnarldin as possible. De two of us should work together! I be helpin' you get recognized as an amani warrior, yeah? Just go out dere and get as many trophies from de gnarldin as possible. I be stayin' behind ta watch our backs, eh?",questType="standard"},
[93608] = {id=93608,name="A Burning Path Through Time",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="On the other side of the Dark Portal lies Outland. I've never been--my history is tied to the Kirin Tor rather than Silvermoon. Yet the elves of Quel'Thalas went through much turmoil during that period of time. Perhaps you could learn a thing or two from that fractured world. Take up the challenge, if you feel worthy of it.",starts={{npcID=256212,x=0.488,y=0.646,mapID=2393}},ends={{npcID=256212,x=0.488,y=0.646,mapID=2393}},coords={x=0.488,y=0.646,source="quest_giver",mapID=2393},questType="standard"},
[93613] = {id=93613,name="A Savage Path Through Time",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Perhaps you can untangle the depth of knowledge to be found in Draenor--not the shattered remains of Outland, but the Draenor of the Iron Horde. It is, in its own ways, just as harsh if not harsher than Outland ever was. See what wisdom you can find there.",starts={{npcID=256212,x=0.488,y=0.646,mapID=2393}},ends={{npcID=256212,x=0.488,y=0.646,mapID=2393}},coords={x=0.488,y=0.646,source="quest_giver",mapID=2393},questType="standard"},
[93628] = {id=93628,name="A Shadowed Path Through Time",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Would you return to the realm of death and risk your very existence? Rebirth, eternal peace, endless torment? All can be found across the veil. Travel to the Shadowlands once more. If you can defeat its most dangerous places, perhaps you will return to the living wiser and more powerful.",starts={{npcID=256212,x=0.488,y=0.646,mapID=2393}},ends={{npcID=256212,x=0.488,y=0.646,mapID=2393}},coords={x=0.488,y=0.646,source="quest_giver",mapID=2393},questType="standard"},
