[93713] = {id=93713,name="Essential Materials",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="The Horde's penchant for teeth and animal pelts has worn off on some sin'dorei. It's not uncommon in recent years to receive bulk orders for both. This is one of those times. If you have any spare hides, or come across any particularly sharp teeth in your hunts, I'd gladly trade you for them.",starts={{npcID=243527,x=0.432,y=0.556,mapID=2393}},ends={{npcID=243527,x=0.432,y=0.556,mapID=2393}},coords={x=0.432,y=0.556,source="quest_giver",mapID=2393},questType="standard"},
[93782] = {id=93782,name="Conditional - Multiple Objectives, Sequenced",level=83,requiredLevel=83,faction="none",expansion=11,zoneID=14998,description="I be sent out here ta prove dat I can be an amani warrior. Dis trial needs me ta collect as many trophies from dese gnarldin as possible. De two of us should work together! I be helpin' you get recognized as an amani warrior, yeah? Just go out dere and get as many trophies from de gnarldin as possible. I be stayin' behind ta watch our backs, eh?",questType="standard"},
[93783] = {id=93783,name="Conditional - Just One Objective",level=83,requiredLevel=83,faction="none",expansion=11,zoneID=14998,description="I be sent out here ta prove dat I can be an amani warrior. Dis trial needs me ta collect as many trophies from dese gnarldin as possible. De two of us should work together! I be helpin' you get recognized as an amani warrior, yeah? Just go out dere and get as many trophies from de gnarldin as possible. I be stayin' behind ta watch our backs, eh?",questType="standard"},
[93798] = {id=93798,name="Renowned with Zul'jarra's Forces",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,description="Dis struggle would have been lost ages ago without you on our side. Now, we live to fight another day. Zul'jarra wishes to honor your efforts with a gift. Come speak to me in Tokka's Landing to receive it.",questType="standard"},
[93852] = {id=93852,name="Lost Iridescent Flightstone",level=1,requiredLevel=1,faction="both",expansion=11,zoneID=13862,mapID=2112,description="The flightstone glimmers with the colors of all aspects. Within the glittering light you have visions of noble dragon houses locked in battle against Primal Incarnates. A vicious cacophony of roars as Shadowflame consumes swaths of land. And the soothing sounds of nature as a world tree blooms. The soaring skies of Valdrakken call.",ends={{npcID=255019,x=0.814,y=0.47,mapID=2112}},questType="standard"},
