[93969] = {id=93969,name="Call Shot",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15969,mapID=2393,description="Critters of all kind are crawling around Eversong and beyond. Cute, cuddly, creepy--whatever strikes your fancy. Ya might be used to havin' varmints bash heads until one was weak enough to nab. Got a new way to try. All you need is a crate. You've got one, yeah? Just throw the crate from the start. It's mighty effective, I tell ya. You look tough enough to nab your own. Why don't ya give it a try?",questType="standard"},
