[94423] = {id=94423,name="Sanctum Secure",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16648,mapID=2405,description="Our control here is only the beginning. Xal'atath has left other pockets of anomalies across the land. The defenses we've devised here can be used to secure those areas as well. Travel to Sunkiller Sanctum and construct five additional defenses to solidify our hold on that location. I will supply the Stormarion Core necessary to activate those defenses.",questType="standard"},
