[94869] = {id=94869,name="Hungry Hungry Hatchlings",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=15947,mapID=2437,description="We will soon be blessed with eggs! Jan'alai has told me so. And once dem eggs hatch, we'll have many hungry mouths to feed! Dey will crave somethin' soft, delicate, and pungent. Ya best scurry down to de shore and find somethin' to tempt de hatchlings with or dey may take a nibble out of you!",starts={{npcID=245512,x=0.55,y=0.182,mapID=2437}},ends={{npcID=621773,x=0.551,y=0.183,mapID=2437}},coords={x=0.55,y=0.182,source="quest_giver",mapID=2437},questType="standard"},
