[95021] = {id=95021,name="Prey: Janoa the Fang (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,description="This creature has established a reputation for particularly vicious ambushes. Envenomed fangs flashing in the dark, followed by frenzied thrashing and then... stillness. See if you cannot give it a taste of its own venom.",questType="standard"},
[95022] = {id=95022,name="Prey: Kursak the Coiled (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,description="Do not let this serpentine monstrosity get close, $p, lest you have the life squeezed out of you. My servants recently found one of its unfortunate victims. Like a fistful of mashed grapes... Apologies, I lost myself for a moment there.",questType="standard"},
[95023] = {id=95023,name="Prey: Batani the Scaled (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,description="I have heard that this creature has scales so thick and sharp you could use them to filet a fish. Do not let its diminutive stature fool you, $p, it was bred for one purpose. To kill. Fortunately, not being killed is something you've grown quite proficient in.",questType="standard"},
[95024] = {id=95024,name="Prey: Kadani the Claw (Nightmare)",level=90,requiredLevel=90,faction="none",expansion=11,description="The claw! A miracle of the natural world. An appendage located at the cutting edge of murderous millennia. This creature is all claw and cunning, and you would do best to not fall prey to its violent nature.",questType="standard"},
