[95780] = {id=95780,name="Hope for the Orphans",level=83,requiredLevel=83,faction="both",expansion=11,zoneID=3703,mapID=111,description="Garona and I both don't talk about our childhoods much. There's not a lot worth saying. The children in that orphanage in Shattrath--they're living what we lived. I'm not asking you to fix that. I'm asking you to show up and remind them the world holds something worth fighting for. For me, revenge was worth fighting for. But maybe they can have a brighter future. Go play games with them. Try to show them what a person worth looking up to actually is.",starts={{npcID=259335,x=0.556,y=0.646,mapID=2541}},ends={{npcID=259335,x=0.556,y=0.646,mapID=2541}},coords={x=0.556,y=0.646,source="quest_giver",mapID=111},questType="standard"},
[95781] = {id=95781,name="No Wax Like Home",level=83,requiredLevel=83,faction="none",expansion=11,zoneID=10473,mapID=2541,questType="standard"},
[95842] = {id=95842,name="Midnight: Void Assaults",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Both Void forces and old enemies press us in this turbulent time. We must stay vigilant and let no faction gain a foothold. You must put a stop to these Void assaults! Stay alert, our scouts report some factions may be using the smaller strikes to prepare for a major incursion. If so, I know you will help with the defense.",ends={{npcID=256203,x=0.49,y=0.646,mapID=2393}},questType="standard"},
[95843] = {id=95843,name="Midnight: Ritual Sites",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="There have been many enemies that seek to use dark rituals to send horrors our way. The rangers have always risen to challenge and dealt with them. With the pressure on our forces, I must ask you to take up this mission. There are dangerous Ritual Sites that must be disrupted. Our enemies will most likely try again, so you must be dogged and continue to thwart them each time they make the attempt.",ends={{npcID=256203,x=0.49,y=0.646,mapID=2393}},questType="standard"},
