[96110] = {id=96110,name="Venom Fishing: Proof is in the Ooze",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="If ye mean to be part of my crew, ye best be ready to handle the venom curse. Know how to fish? Every creature with gills on this isle is ready to sink its teeth into you. Prove ye can fish up even the smallest of the venom-cursed fish and I'll show ye how to take on deadlier and nastier fishin'.",starts={{npcID=258755,x=0.572,y=0.486,zoneID=16365}},ends={{npcID=258755,x=0.572,y=0.486,zoneID=16365}},coords={x=0.572,y=0.486,source="quest_giver",zoneID=16365},questType="standard"},
[96111] = {id=96111,name="Venom Fishing: Shell of Yourself",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="You've learned some o' my secrets to fishin' in these cursed waters, but everything ye learn from here on serves a greater purpose than survival. Revenge. The Great White Serpent that sank my ship is still alive. If we intend to kill it, we need the power o' my crew, now lost to the venom-curse. Master Grenadier Birdie has one good shot: her first shot. Build yerself a decoy and you'll have a chance to kill her. Take her explosives. We'll need 'em to blow that snake to smithereens.",starts={{npcID=258755,x=0.572,y=0.486,zoneID=16365}},ends={{npcID=258755,x=0.572,y=0.486,zoneID=16365}},coords={x=0.572,y=0.486,source="quest_giver",zoneID=16365},questType="standard"},
[96112] = {id=96112,name="Venom Fishing: Maddening Concoction",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="We need somethin' to protect that shell-less back o' yers when we face the Great White Serpent. Leathertongue made dishes that made us immune to nigh anything, this being on account o' them nearly killin' us every mealtime! His pots and pans could withstand any nightmare. We need that strength. The key to defeating the cook is to challenge his skill. Make a dish of the foulest ingredients and he'll be there to face ye.",starts={{npcID=258755,x=0.572,y=0.486,zoneID=16365}},ends={{npcID=258755,x=0.572,y=0.486,zoneID=16365}},coords={x=0.572,y=0.486,source="quest_giver",zoneID=16365},questType="standard"},
[96113] = {id=96113,name="Venom Fishing: Maximum Potency",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,description="We're almost ready to face the Great White Serpent. We only need one more thing. I want ye to take my quartermaster's boat. Inktail has plans on plans. Before the venom, she was cool and reserved even in the wildest storms. With the venom curse, she's become even more elusive. I've only seen her lose her deadly composure once. She has a mighty love of rare fish. It's a gamble, but go into the temple and find a fish overwhelmed with venom. It may be enough to draw her out of hidin'.",questType="standard"},
[96114] = {id=96114,name="A Small Pouch of Crystals",level=70,requiredLevel=70,faction="both",expansion=11,zoneID=15347,mapID=2346,starts={{npcID=231409,x=0.436,y=0.508,mapID=2346}},ends={{npcID=231409,x=0.436,y=0.508,mapID=2346}},coords={x=0.436,y=0.508,source="quest_giver",mapID=2346},questType="standard"},
