[96123] = {id=96123,name="A Small Bundle of Goods",level=70,requiredLevel=70,faction="both",expansion=11,zoneID=14771,mapID=2339,starts={{npcID=223728,x=0.392,y=0.242,mapID=2339}},ends={{npcID=223728,x=0.392,y=0.242,mapID=2339}},coords={x=0.392,y=0.242,source="quest_giver",mapID=2339},questType="standard"},
[96124] = {id=96124,name="A Small Bundle of Goods",level=70,requiredLevel=70,faction="both",expansion=11,zoneID=14771,mapID=2339,starts={{npcID=223728,x=0.392,y=0.242,mapID=2339}},ends={{npcID=223728,x=0.392,y=0.242,mapID=2339}},coords={x=0.392,y=0.242,source="quest_giver",mapID=2339},questType="standard"},
[96224] = {id=96224,name="The Magisters' Conundrum",level=80,requiredLevel=80,faction="alliance",expansion=11,zoneID=17067,description="Magisters' Terrace is home to many mysterious artifacts. Among them is a relic once central to our pursuit of magical knowledge. A few years ago, the relic fell into a state of dormancy. After the Dawnwell reignited, this artifact began to stir. Upon returning it to the Lycaneum for study, the relic unleashed chaos upon the library. I believe your unique expertise may be helpful in quelling this chaos.",starts={{npcID=264063,x=0.388,y=0.486,mapID=2393}},ends={{npcID=264066,x=0.636,y=0.166,zoneID=17067}},coords={x=0.388,y=0.486,source="quest_giver",zoneID=15969},questType="standard"},
[96225] = {id=96225,name="The Magisters' Conundrum",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=17067,description="For the last few decades, a dormant artifact laid beneath the halls of Magisters' Terrace. Once serving as a beacon of knowledge to the Magisters, the artifact abruptly fell silent some decades ago. After the Dawnwell's rebirth, the artifact reawakened. When we returned it to the Lycaneum for study, it unleashed chaos upon the library. Your assistance, and discretion, would be most appreciated.",starts={{npcID=264064,x=0.388,y=0.486,mapID=2393}},ends={{npcID=264065,x=0.624,y=0.154,zoneID=17067}},coords={x=0.388,y=0.486,source="quest_giver",zoneID=15969},questType="standard"},
[96226] = {id=96226,name="Omnium Anomalies",level=80,requiredLevel=80,faction="alliance",expansion=11,zoneID=16215,mapID=2424,description="Shortly after the Omnium awoke, it began manifesting arcane anomalies around the Lycaneum. We believe these anomalies to be malfunctioning security protocols--the hostile projections they conjure can be quite lethal. If we do not dispatch them quickly, they will continue to manifest. As you deal with them, keep an eye out for anything peculiar that can help us understand the Omnium's current state.",starts={{npcID=264065,x=0.624,y=0.154,zoneID=17067}},ends={{npcID=264065,x=0.624,y=0.154,zoneID=17067}},coords={x=0.624,y=0.154,source="quest_giver",mapID=2424},questType="standard"},
[96227] = {id=96227,name="Lycaneum Chaos",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=17067,description="When the Omnium began to stir in its vault, we thought to move it here for observation. Evidently, this was a bad idea. The arcane magics seeping out are causing chaos. Folios casting all sorts of incomplete spells, arcane sparks running amok--even the candle flames have sprung to life! But we cannot simply destroy them, as the magics here are too volatile. I have procured a ward-lance from the arsenal of the spellbreakers. It will dispel the volatile magic. Here, take it. And do be careful.",starts={{npcID=264066,x=0.636,y=0.166,zoneID=17067}},ends={{npcID=264066,x=0.636,y=0.166,zoneID=17067}},coords={x=0.636,y=0.166,source="quest_giver",zoneID=17067},questType="standard"},
[96228] = {id=96228,name="The Shadowed Spire",level=80,requiredLevel=80,faction="alliance",expansion=11,zoneID=15968,mapID=2395,description="Time and time again, Dar'Khan continues to haunt us in some form. To think the Omnium also fell prey to his madness... If he really severed the Void Magicule from the Omnium, then I have no doubt he would have hidden it well. I have a suspicion I know where to start looking. Meet me at Dawnstar Spire in Eversong Woods.",starts={{npcID=264065,x=0.624,y=0.154,zoneID=17067}},ends={{npcID=264067,x=0.626,y=0.63,mapID=2395}},coords={x=0.624,y=0.154,source="quest_giver",mapID=2395},questType="standard"},
[96229] = {id=96229,name="The Void Reveals",level=80,requiredLevel=80,faction="alliance",expansion=11,zoneID=15968,mapID=2395,description="After reclaiming Silvermoon, the Magisters torched Dar'Khan's personal study and dwellings within the city walls. I had thought I had found everything I needed the first time I searched this place, but now... It seems that Dar'Khan left some secrets. This portal will take us to them. I do not know what we will find on the other side. Be on your guard.",starts={{npcID=264067,x=0.626,y=0.63,mapID=2395}},ends={{npcID=269814,x=0.624,y=0.626,mapID=2395}},coords={x=0.626,y=0.63,source="quest_giver",mapID=2395},questType="standard"},
[96230] = {id=96230,name="Unraveling the Wards",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16215,mapID=2424,description="The Magicules, the orbs you see on the relic, were never meant to be severed from the Omnium. By tearing one out, Dar'Khan likely sent the artifact into a frenzied state before it shut down. Even if the Void Magicule is restored, the Omnium will need recalibrating. We will need Belo'vir's key-cipher, now my key-cipher, to do this. I will meet you at my study and we can recover it.",starts={{npcID=264066,x=0.636,y=0.166,zoneID=17067}},ends={{npcID=264945,x=0.588,y=0.574,mapID=2424}},coords={x=0.636,y=0.166,source="quest_giver",mapID=2424},questType="standard"},
[96231] = {id=96231,name="The Grand Magister's Key-Cipher",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16215,mapID=2424,description="After Belo'vir's death, I contemplated opening this vault. I talked myself out of it. A key for a shattered lock serves no purpose. And yet, even as Kael'thas tried to open it with his key, I couldn't help but wonder... It doesn't matter, . I am nearly done with the master ward on the upper floor. Meet me there. No doubt, Belo'vir took extra steps to safeguard his vault.",starts={{npcID=264945,x=0.588,y=0.574,mapID=2424}},ends={{npcID=264944,x=0.59,y=0.592,mapID=2424}},coords={x=0.588,y=0.574,source="quest_giver",mapID=2424},questType="standard"},
[96232] = {id=96232,name="Return to the Omnium",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=17067,description="Well, now that we've recovered the piece Dar'Khan stole, we are one step closer to restoring the Omnium. Hopefully your endeavor with Rommath was a little less troublesome? When you're ready, return to the Magisters' Terrace. I will clean up anything left behind here and join you shortly.",starts={{npcID=269814,x=0.624,y=0.626,mapID=2395}},ends={{npcID=264066,x=0.636,y=0.166,zoneID=17067}},coords={x=0.624,y=0.626,source="quest_giver",zoneID=15968},questType="standard"},
[96233] = {id=96233,name="The Omnium Reawakens",level=80,requiredLevel=80,faction="alliance",expansion=11,zoneID=17067,description="For years, as Silvermoon and its people changed, this relic sat in a vault beneath the Terrace, unresponsive and dormant. We may never truly understand why the relic fell silent when it did or why it refused the prince's call, but perhaps in time, we might. Let us hope the missing Magicule and the key-cipher will be enough to restore it. Are you ready, ?",starts={{npcID=264066,x=0.636,y=0.166,zoneID=17067}},ends={{npcID=264069,x=0.604,y=0.112,zoneID=17067}},coords={x=0.636,y=0.166,source="quest_giver",zoneID=17067},questType="standard"},
[96238] = {id=96238,name="Return to the Omnium",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=17067,description="With Belo'vir's key-cipher recovered and Umbric in possession of the Void Magicule, we should return to the Lycaneum. Hopefully we have all that we need to recalibrate the Sunstrider Omnium. I will meet you back in the Magisters' Terrace when I am done here.",starts={{npcID=264944,x=0.59,y=0.592,mapID=2424}},ends={{npcID=264066,x=0.636,y=0.166,zoneID=17067}},coords={x=0.59,y=0.592,source="quest_giver",zoneID=16215},questType="standard"},
[96307] = {id=96307,name="Special Assignment: Wraith Wrath",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,questType="standard"},
[96310] = {id=96310,name="Disrupting the Order",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="Great work defeating their forces. Every step we take will keep Azeroth safe. But usurpers are still trying to seize control. Baraat has already spotted high ranking domanaar looking at the remaining resources. We need to defeat the Umbrawardens and any of their forces along the way.",starts={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},ends={{npcID=265166,x=0.668,y=0.425,zoneID=16900}},coords={x=0.596,y=0.218,source="quest_giver",zoneID=16900},questType="standard"},
[96338] = {id=96338,name="Port of Entry",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description=", take a look at that platform above. What do you think they use that for? The void creatures steal wildlife from Azeroth and move them here to be broken, then added to their forces. That platform must be where creatures are first brought in. Let's force our way through any defenses up there and destroy that portal!",starts={{npcID=265166,x=0.668,y=0.425,zoneID=16900}},ends={{npcID=265166,x=0.668,y=0.425,zoneID=16900}},coords={x=0.668,y=0.425,source="quest_giver",zoneID=16900},questType="standard"},
[96382] = {id=96382,name="A New Approach",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="For this threat, you'll need to think more like the domanaar. Luckily, I can do just that. What we need is a puppet. Someone we can give the reins who has no aspirations for your precious Azeroth. Those new domanaar you saw will need evaluation. Take this veil. You'll be able to blend in and observe them. I understand your urge to strike, but be patient. The time will come to eliminate all in your path, as your kind seems to enjoy. See if you can find a proper candidate.",starts={{npcID=264879,x=0.598,y=0.218,zoneID=16900}},coords={x=0.598,y=0.218,source="quest_giver",zoneID=16900},questType="standard"},
[96389] = {id=96389,name="A Place to Negotiate",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="While you were attuning the gem to the Void, I managed to acquire one of Impotus's projection devices. We're going to use it to lure him to us, then prevent him from escaping with the gem. Not here, though. Let us find somewhere more discrete.",ends={{npcID=267877,x=0.589,y=0.695,zoneID=16900}},questType="standard"},
[96410] = {id=96410,name="Seeking Knowledge Week 1 of 5: The Omnium Folio",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=17067,description="Those who sought to learn from the Omnium had to contribute to it. While most Magisters studied within the Terrace, a select few were appointed as \"Seekers of Wisdom.\" Seekers would search for new and foreign magic to contribute to the Omnium's vast index for study. Given your... adventurous experience, I think you'd make an excellent seeker. If you're interested, the Grand Magister will explain more.",starts={{npcID=264069,x=0.604,y=0.112,zoneID=17067}},ends={{npcID=264070,x=0.602,y=0.116,zoneID=17067}},coords={x=0.604,y=0.112,source="quest_giver",zoneID=17067},questType="standard"},
[96439] = {id=96439,name="Gone Dark",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="These infernal nests are where de Children of Ula'tek spawn from. We must work to clear dem out if we are to have any hope of stemming de endless tide of snakes. I have been sending groups of my most fearless scouts to gather information on dem. All have returned... except for one. Go, track down Ulantu and Naj'kula in de Blistering Terrace. Find out why dey gone dark.",starts={{npcID=265173,x=0.578,y=0.466,zoneID=16365}},coords={x=0.578,y=0.466,source="quest_giver",zoneID=16365},questType="standard"},
[96440] = {id=96440,name="Victory Within Hindsight",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="Great work, ! I can already picture the walls of the Acropolis crumbling. In fact, why don't we head there now and press our advantage? The Light can shine through the tiniest of cracks. I'll scout ahead and meet you on the way there.",starts={{npcID=265166,x=0.668,y=0.425,zoneID=16900}},ends={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},coords={x=0.668,y=0.425,source="quest_giver",zoneID=16900},questType="standard"},
[96441] = {id=96441,name="Seeking Knowledge Week 2 of 5: Ritualized Arcana",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=17067,description="The nature of the Dawnwell has sparked a question among the minds of Magisters' Terrace: If magic can corrupt and suffuse other magics, how will the Dawnwell affect the ley lines branching out from it? With inquiry, comes experiment. The Ritual Sites in Quel'Thalas use the ley lines to fuel their magic. Disrupt these sites and retrieve samples of the arcana you find.",starts={{npcID=264069,x=0.604,y=0.112,zoneID=17067}},ends={{npcID=264070,x=0.602,y=0.116,zoneID=17067}},coords={x=0.604,y=0.112,source="quest_giver",zoneID=17067},questType="standard"},
[96442] = {id=96442,name="Seeking Knowledge Week 3 of 5: Ley Line Assaults",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=17067,description="Unfortunately, most of the measurable samples were expunged by the Ritual Site's excessive energy. If we are to accurately measure the various magics seeping into the ley lines, we'll need samples from a broader, less concentrated source. I am told the Farstriders continue to route the void strikes across Quel'Thalas. Bring me coalesced ley energy from any of the assaulting forces.",starts={{npcID=264070,x=0.602,y=0.116,zoneID=17067}},ends={{npcID=264069,x=0.604,y=0.112,zoneID=17067}},coords={x=0.602,y=0.116,source="quest_giver",zoneID=17067},questType="standard"},
[96443] = {id=96443,name="Seeking Knowledge Week 4 of 5: Magical Primessence",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=17067,description="Thanks to your efforts, we've isolated the effects of trace amounts of foreign magic coalescing with the ley lines. Our next phase is to compare these results against a pure sample of magic coalescing with the same energy. Your task is to track down a primessence of magic--be it arcane, Void, Light, or other--and acquire it from its deadly source. Good luck, .",starts={{npcID=264070,x=0.602,y=0.116,zoneID=17067}},ends={{npcID=264069,x=0.604,y=0.112,zoneID=17067}},coords={x=0.602,y=0.116,source="quest_giver",zoneID=17067},questType="standard"},
[96444] = {id=96444,name="Seeking Knowledge Week 5 of 5: Off-World Magic",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=17067,description="Although it made an excellent catalyst, the primessence you retrieved revealed a factor we did not account for. The alien nature of the Void and ethereal magic used in their assaults proved incompatible with the experiment. We need a sample of their magic if we are to make any progress--not from the assaults here in Quel'Thalas, but from the source of their attacks. I am told these enemies strike from off-world staging grounds. Good luck, .",starts={{npcID=264069,x=0.604,y=0.112,zoneID=17067}},ends={{npcID=264070,x=0.602,y=0.116,zoneID=17067}},coords={x=0.604,y=0.112,source="quest_giver",zoneID=17067},questType="standard"},
[96450] = {id=96450,name="Sideways",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Naj'kula and I were here to observe how the Children of Ula'tek reproduce. We discovered dis lich, Lokago. Malacrass had him experimentin' on kidnapped Amani. I stole his records to try and figure out why, but de lich discovered us. I was injured. I dropped everythin'. Naj'kula was right behind me... We gotta recover de notes--and find Naj'kula!",questType="standard"},
[96451] = {id=96451,name="A Child of Ula'tek",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="I don't like dis. We should have found her by now. Ulantu 's face is sweaty and pale. She rubs her wound absentmindedly.> De lich must have dragged her back to where he was doin' his experiments. And if his notes are to be believed... We need to find Naj'kula quickly--or she may not be who she was.",questType="standard"},
[96457] = {id=96457,name="Nothing Must Remain",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="You saw what he did to Naj'kula. And who knows how many others. Ulantu is sweating and pale, gripping her stomach.> Too many lives were sacrificed in de name of these awful... whatever Kuku became. If only we could have killed de damned lich! But we can destroy his lab.",questType="standard"},
[96467] = {id=96467,name="Thirst for Knowledge",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Two brothers came with us to dis cursed place... Zei'ka and Jun'ka. Zei'ka , he got de fire in him. Soon as we landed, he ran off, chasing whispers like dey were calling his name. But, Jun'ka, he ain't a fool. He went after his brother, tryin' to keep him from getting himself killed. I don't like dis. Dis island, it'll swallow us whole if we ain't careful. Go check on dem, eh?",starts={{npcID=265173,x=0.578,y=0.466,zoneID=16365}},ends={{npcID=265329,x=0.75,y=0.626,zoneID=16365}},coords={x=0.578,y=0.466,source="quest_giver",zoneID=16365},questType="standard"},
[96469] = {id=96469,name="The Crypt of the Disgraced",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Jun'ka's my brother, but he frets too much to let me chase after my life's dream. Ever since I was a child, I wanted to learn more of our history. While much of it is told by de talespinners back home, they always skipped one thing: Atal'Utek. De more I dug, de more mysterious it became, and de more I became engrossed. Now, de scouts tell me that this crypt is filled with tablets inside. Tablets that could have de history of our people. I need to see those tablets, even if it kills me. You in?",starts={{npcID=265329,x=0.75,y=0.626,zoneID=16365}},coords={x=0.75,y=0.626,source="quest_giver",zoneID=16365},questType="standard"},
[96471] = {id=96471,name="Crumble and Tumble",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Blast it all! I dragged y'all into dis muck just 'cause my brother's worried about my hide! You're gettin' outta here quick! I lead, you follow, and don't lag behind, or you're squashed!",ends={{npcID=267032,x=0.748,y=0.624,zoneID=16365}},questType="standard"},
[96473] = {id=96473,name="Imperator Pertinax",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="Like all domanaar, Imperator Pertinax sees himself only as a predator and never the prey. Unfortunately, our prey is well-guarded in his Void Acropolis. If you manage to gather enough allies and catch the imperator off guard, we'll deal a crushing blow to our enemies. Move swiftly and cautiously, , and ensure you have backup before engaging Pertinax.",starts={{npcID=263987,x=0.416,y=0.846,zoneID=16900}},ends={{npcID=264879,x=0.598,y=0.218,zoneID=16900}},coords={x=0.416,y=0.846,source="quest_giver",zoneID=16900},questType="group"},
[96492] = {id=96492,name="Special Assignment: Demand and Supply",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,questType="standard"},
[96498] = {id=96498,name="Grovewarden's Kris",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,starts={{npcID=251259,x=0.492,y=0.544,mapID=2413}},ends={{npcID=251259,x=0.492,y=0.544,mapID=2413}},coords={x=0.492,y=0.544,source="quest_giver",mapID=2413},questType="standard"},
