[96502] = {id=96502,name="Vivid Chloroceros",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,starts={{npcID=251259,x=0.492,y=0.544,mapID=2413}},ends={{npcID=251259,x=0.492,y=0.544,mapID=2413}},coords={x=0.492,y=0.544,source="quest_giver",mapID=2413},questType="standard"},
[96503] = {id=96503,name="Prey: A Ghostly Nightmare",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="It appears your scouting has born fruit. This power could prove a useful boon indeed. Return to Atal'Utek and siphon its magic for our glorious purpose.",starts={{npcID=246231,x=0.566,y=0.654,mapID=2393}},ends={{npcID=246231,x=0.566,y=0.654,mapID=2393}},coords={x=0.566,y=0.654,source="quest_giver",zoneID=15969},questType="standard"},
[96504] = {id=96504,name="Warm Haranir Blanket",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,starts={{npcID=251259,x=0.492,y=0.544,mapID=2413}},ends={{npcID=251259,x=0.492,y=0.544,mapID=2413}},coords={x=0.492,y=0.544,source="quest_giver",mapID=2413},questType="standard"},
