[96509] = {id=96509,name="Grovewarden's Greatsword",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,starts={{npcID=251259,x=0.492,y=0.544,mapID=2413}},ends={{npcID=251259,x=0.492,y=0.544,mapID=2413}},coords={x=0.492,y=0.544,source="quest_giver",mapID=2413},questType="standard"},
[96510] = {id=96510,name="Elder Glowmite",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15355,mapID=2413,starts={{npcID=251259,x=0.492,y=0.544,mapID=2413}},ends={{npcID=251259,x=0.492,y=0.544,mapID=2413}},coords={x=0.492,y=0.544,source="quest_giver",mapID=2413},questType="standard"},
[96523] = {id=96523,name="Living Legend",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="These soldiers--dey are too young to remember the time before de loa gave us their help. So de loa can't come here. So? Let me tell a legend dat takes place before the loa helped our kind. Maybe you heard of it? Or maybe you want to see it for yourself...",starts={{npcID=265476,x=0.594,y=0.508,zoneID=16365}},ends={{npcID=265660,x=0.454,y=0.482,mapID=2437}},coords={x=0.594,y=0.508,source="quest_giver",mapID=2437},questType="standard"},
[96525] = {id=96525,name="Prey: Out of Our Depth",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="This is more than I'm prepared to deal with. I'll open a portal back to the Sanctum. I'm going to wait for these blasted little snakelings to grow tired of me before following you through. Do put in a good word for me, please.",starts={{npcID=265267,x=0.582,y=0.486,zoneID=16365}},ends={{npcID=246231,x=0.566,y=0.654,mapID=2393}},coords={x=0.582,y=0.486,source="quest_giver",mapID=2393},questType="standard"},
[96532] = {id=96532,name="Prey: Attending the Attendant",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="My methods might come across as cruel and unusual to some, but I do take to heart the well being of those who serve under me. Most of the time. Attendant Ethrandil has served our cause admirably. Please let him know he can return to me. These floors have grown noticeably dirtier as of late...",starts={{npcID=246231,x=0.566,y=0.654,mapID=2393}},ends={{npcID=265529,x=0.57,y=0.332,zoneID=16365}},coords={x=0.566,y=0.654,source="quest_giver",zoneID=15969},questType="standard"},
[96534] = {id=96534,name="Preparing for Threats",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="My brother has always been the creative one, his hands busy on some intricate side project or some device he's working on. His enthusiasm will benefit this operation greatly, especially when it comes to thwarting the threats we face on this world. See what he's been working on and give one of his new experiments a trial run. I'm sure he'll be thrilled at the opportunity to contribute.",starts={{npcID=265558,x=0.478,y=0.814,zoneID=16943}},ends={{npcID=265558,x=0.478,y=0.814,zoneID=16943}},coords={x=0.478,y=0.814,source="quest_giver",zoneID=16943},questType="standard"},
[96539] = {id=96539,name="Last Resort",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Long, long ago, there was a village that suffered from a great drought. De crops wouldn't grow, and the land dried up. De whole village was starving! The villagers came to one troll--Jeytha--to ask her a favor. In dis story, you are Jeytha--now go see what those hungry villagers want!",starts={{npcID=265660,x=0.454,y=0.482,mapID=2437}},ends={{npcID=265661,x=0.444,y=0.48,mapID=2437}},coords={x=0.454,y=0.482,source="quest_giver",mapID=2437},questType="standard"},
[96540] = {id=96540,name="Strong Hands",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Jeytha came across a fox in de path, beset by lynx. And she was kind, and unafraid, and strong--so she decided to help that fox out. Now go tell those lynx to get outta here!",starts={{npcID=265661,x=0.444,y=0.48,mapID=2437}},ends={{npcID=265662,x=0.436,y=0.478,mapID=2437}},coords={x=0.444,y=0.48,source="quest_giver",mapID=2437},questType="standard"},
[96541] = {id=96541,name="Strong Mind",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="That sly old fox wasn't just any fox! He spoke, and he ran, and he waited for Jeytha to meet him. Now what did he want with Jeytha? You should talk to him and find out!",starts={{npcID=265662,x=0.436,y=0.478,mapID=2437}},ends={{npcID=265660,x=0.454,y=0.482,mapID=2437}},coords={x=0.436,y=0.478,source="quest_giver",mapID=2437},questType="standard"},
[96543] = {id=96543,name="Root of Survival",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Now dat she was back where she started, Jeytha knew she couldn't make that journey. But what of de starving villagers? How would they survive? Jeytha had a few ideas... if the villagers would listen to her. Go see what she has to say!",starts={{npcID=265660,x=0.454,y=0.482,mapID=2437}},ends={{npcID=269367,x=0.454,y=0.484,mapID=2437}},coords={x=0.454,y=0.482,source="quest_giver",mapID=2437},questType="standard"},
[96544] = {id=96544,name="Bravely Burning",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="Years passed, and she didn't use dat third boon. One year, a flight of angry dragonhawks set their eyes--and flames--on de village. Her son was trapped, their home on fire! \"I could use my boon,\" thought Jeytha, \"But why use my boon, when I can use my strength?\" Go show those dragonhawks your strength, and save dat boy!",starts={{npcID=265660,x=0.454,y=0.482,mapID=2437}},ends={{npcID=265666,x=0.456,y=0.49,mapID=2437}},coords={x=0.454,y=0.482,source="quest_giver",mapID=2437},questType="standard"},
[96545] = {id=96545,name="Strong Voice",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="The years passed, and still Jeytha did not use dat third boon. One year, a group of raiders arrived at de village, looking to steal everything dey had. \"I could use dat third boon,\" Jeytha thought, \"But why use dat boon when I can use my voice?\" Go talk those raiders down--and if dey don't listen, use your strength and change their minds!",starts={{npcID=265666,x=0.456,y=0.49,mapID=2437}},ends={{npcID=265668,x=0.452,y=0.486,mapID=2437}},coords={x=0.456,y=0.49,source="quest_giver",mapID=2437},questType="standard"},
[96546] = {id=96546,name="Strong Heart",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="The years passed, and Jeytha felt her time coming. She'd lived a long life, full of struggles but still happy. But as Jeytha reached the end of her days, dat sly old fox appeared. \"Wait!\" he said. \"You can't go yet!\" Now what does that fox want? Go talk to him and find out!",starts={{npcID=265668,x=0.452,y=0.486,mapID=2437}},ends={{npcID=265476,x=0.594,y=0.508,zoneID=16365}},coords={x=0.452,y=0.486,source="quest_giver",zoneID=15947},questType="standard"},
[96567] = {id=96567,name="Data Decryption Disaster",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="To understand the Hal'hadar's intentions with this world, we will need to secure information. Knowing how they operate, they've restricted their data consoles with security measures in place. This decrypter will automatically navigate their security. If you choose, you can engage the manual option to hasten the protocol. Just remember to ignore any security warnings. My device can and will bypass it.",starts={{npcID=266034,x=0.478,y=0.82,zoneID=16943}},ends={{npcID=266034,x=0.478,y=0.82,zoneID=16943}},coords={x=0.478,y=0.82,source="quest_giver",zoneID=16943},questType="standard"},
[96568] = {id=96568,name="Hal'hadon't You Dare!",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="Y'mera's plan to intercept their data consoles will no doubt trigger heightened security protocols. Normally, no-contact reconnaissance would be advised in this situation, but I think sowing chaos will be more beneficial. The Hal'hadar won't be aware of their stolen data if their entire manaforge is under attack. Dispatch any Hal'hadar agents you find.",starts={{npcID=265950,x=0.476,y=0.82,zoneID=16943}},ends={{npcID=265950,x=0.476,y=0.82,zoneID=16943}},coords={x=0.476,y=0.82,source="quest_giver",zoneID=16943},questType="standard"},
[96569] = {id=96569,name="Conductive Crystals",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,starts={{npcID=654497,x=0.705,y=0.487,zoneID=16943}},ends={{npcID=265559,x=0.478,y=0.812,zoneID=16943}},coords={x=0.705,y=0.487,source="quest_giver",zoneID=16943},questType="standard"},
[96570] = {id=96570,name="Technological Transference",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="The Hal'hadar are notorious for looting and stealing technology from any world they descend upon. Thanks to the intel you helped retrieve, we know they are using the manaforge east of us to experiment on whatever salvage they found. Take this translocator with you and mark anything that doesn't resemble ethereal technology. I will transport it back here for further study.",starts={{npcID=266034,x=0.478,y=0.82,zoneID=16943}},ends={{npcID=266034,x=0.478,y=0.82,zoneID=16943}},coords={x=0.478,y=0.82,source="quest_giver",zoneID=16943},questType="standard"},
[96571] = {id=96571,name="The Node Knows",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="The manaforge to the east serves as both a research site and military compound, making it a valuable target. Much of their research, including holoprint schematics, lays around the forge. The Hal'hadar stationed here also carry nodes containing experimental and logistical data. Take advantage of this accessible intel and bring back what you can find.",starts={{npcID=265950,x=0.476,y=0.82,zoneID=16943}},ends={{npcID=265950,x=0.476,y=0.82,zoneID=16943}},coords={x=0.476,y=0.82,source="quest_giver",zoneID=16943},questType="standard"},
[96572] = {id=96572,name="Malfunctioning Nullframe",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,ends={{npcID=266034,x=0.478,y=0.82,zoneID=16943}},questType="standard"},
[96573] = {id=96573,name="Soul Lattice Revealed",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="It took some work, but we've cracked their ciphers. The Hal'hadar seek to power their Nullframes using draenei vigilant technology. The \"Soul Lattice\" is a heart for the Nullframe using a vigilant's core. With it, they can bind their unwrapped energy into the core and wear the frame like armor. The Hal'hadar must not succeed in finishing this prototype. Y'mera is planning the next move. Speak with her.",starts={{npcID=265558,x=0.478,y=0.814,zoneID=16943}},ends={{npcID=265950,x=0.476,y=0.82,zoneID=16943}},coords={x=0.478,y=0.814,source="quest_giver",zoneID=16943},questType="standard"},
[96574] = {id=96574,name="Cryptside Rendezvous",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=17103,description="The tomb is called Vilaldoun. It means \"island of the restful.\" Its entrance lies on the northern coast. We know the Hal'hadar have established an extraction site outside the crypt, harvesting the local flora there to fuel their research. As you approach, you will be met with heavy resistance. Cut a path through their ranks while we establish a footing inside and meet us within.",starts={{npcID=265950,x=0.476,y=0.82,zoneID=16943}},ends={{npcID=266829,x=0.754,y=0.442,zoneID=17103}},coords={x=0.476,y=0.82,source="quest_giver",zoneID=16943},questType="standard"},
[96575] = {id=96575,name="Cages of the Soul",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=17103,description="Without the tomb's defenses, the souls of the dead were easy targets for the Hal'hadar. The ethereals intend to use the spirits to fuel the Soul Lattices for the Nullframe. We must not let that happen. Take my scepter and use it to repair the defense wards and shatter the energy cages binding the dead. Once you've finished, regroup with Tala'saan in the lower chambers.",starts={{npcID=266541,x=0.754,y=0.442,zoneID=17103}},ends={{npcID=266540,x=0.362,y=0.728,zoneID=17103}},coords={x=0.754,y=0.442,source="quest_giver",zoneID=17103},questType="standard"},
[96576] = {id=96576,name="Mementos of the Dead",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="Defiling tombs... harnessing innocent souls as fuel... The Hal'hadar are no better than demons. If left unchecked, the ethereals will pilfer every grave and altar down here. I may bear the title of \"Souleater,\" but it doesn't mean I can't honor the dead in this forgotten place. Recover the tributes the ethereals have stolen. Bring them to Tala'saan in the lower chamber.",starts={{npcID=266829,x=0.754,y=0.442,zoneID=17103}},ends={{npcID=266540,x=0.362,y=0.728,zoneID=17103}},coords={x=0.754,y=0.442,source="quest_giver",zoneID=17103},questType="standard"},
[96577] = {id=96577,name="The Soul Architect",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=17103,description="The architect leading their operation has found a single vigilant with an intact construct core. The other vigilants in this chamber appear to be depleted. If she succeeds in creating the Soul Lattice, the Hal'hadar will possess the means to turn our warframes into new armored bodies for their soldiers. We must stop her now and recover the Soul Lattice prototype.",starts={{npcID=266540,x=0.362,y=0.728,zoneID=17103}},ends={{npcID=266540,x=0.362,y=0.728,zoneID=17103}},coords={x=0.362,y=0.728,source="quest_giver",zoneID=17103},questType="standard"},
[96578] = {id=96578,name="Cryptic Departure",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="Although she escaped, we have denied the architect her prototype... for now. This Soul Lattice is fractured, but the core within still hums with a faint energy. Perhaps this vigilant's soul yet remains... If we hurry, perhaps Veraan and her brother can help stabilize the damage to preserve it. I will regroup with Y'mera and Allari and meet you back at camp.",starts={{npcID=266540,x=0.362,y=0.728,zoneID=17103}},ends={{npcID=265558,x=0.478,y=0.814,zoneID=16943}},coords={x=0.362,y=0.728,source="quest_giver",zoneID=17103},questType="standard"},
[96612] = {id=96612,name="Ancient Curiosity: Combat",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15969,mapID=2393,questType="standard"},
[96615] = {id=96615,name="Ancient Curiosity: Utility",level=80,requiredLevel=80,faction="none",expansion=11,zoneID=15969,mapID=2393,questType="standard"},
[96703] = {id=96703,name="Veterans of the Great Dark",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15969,mapID=2393,description="When the Hal'hadar attacked, we quickly learned about their history with the Army of the Light. Commander Tala'saan has been providing us information on these ethereals. His soldiers stand ready to join our cause. I've requested their expertise in establishing a forward camp for our mission. Aid them in their preparations and inform the commander we mobilize soon.",starts={{npcID=263479,x=0.476,y=0.51,mapID=2393}},ends={{npcID=263479,x=0.476,y=0.51,mapID=2393}},coords={x=0.476,y=0.51,source="quest_giver",mapID=2393},questType="standard"},
[96708] = {id=96708,name="To the Voidstorm and Beyond!",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15458,mapID=2405,description="It may not seem like many, but the allies we've secured will have to be enough. It's time we move out. Our forces are gathering at the Howling Ridge. The energies of the Voidstorm will allow us to open the way to these worlds. I will meet you there. There is something here I still require for our mission.",starts={{npcID=263479,x=0.476,y=0.51,mapID=2393}},ends={{npcID=263480,x=0.516,y=0.71,mapID=2405}},coords={x=0.476,y=0.51,source="quest_giver",mapID=2405},questType="standard"},
[96709] = {id=96709,name="The Nexus-Captain (Heroic)",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16943,questType="group"},
[96711] = {id=96711,name="Imperator Pertinax (Heroic)",level=90,requiredLevel=90,faction="none",expansion=11,questType="group"},
[96713] = {id=96713,name="Showdown on Val",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16900,description="Our enemy's hold on Val may be strong, but it is not unbreakable. For every monstrosity we cut down, we deny them another soldier to use against our world. Venture out into the frozen landscape and lay waste to their strongholds. Show them no mercy, .",starts={{npcID=263479,x=0.476,y=0.51,mapID=2393},{npcID=263482,x=0.596,y=0.218,zoneID=16900}},ends={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},coords={x=0.476,y=0.51,source="quest_giver",zoneID=15969},questType="standard"},
[96714] = {id=96714,name="Showdown on Val (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16900,description="Our enemy's hold on Val may be strong, but it is not unbreakable. For every monstrosity we cut down, we deny them another soldier to use against our world. Venture out into the frozen landscape and lay waste to their strongholds. Show them no mercy, .",starts={{npcID=263479,x=0.476,y=0.51,mapID=2393},{npcID=263482,x=0.596,y=0.218,zoneID=16900}},ends={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},coords={x=0.476,y=0.51,source="quest_giver",zoneID=15969},questType="standard"},
[96716] = {id=96716,name="Showdown on Val",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="Our enemy's hold on Val may be strong, but it is not unbreakable. For every monstrosity we cut down, we deny them another soldier to use against our world. Venture out into the frozen landscape and lay waste to their strongholds. Show them no mercy, .",starts={{npcID=263479,x=0.476,y=0.51,mapID=2393},{npcID=263482,x=0.596,y=0.218,zoneID=16900}},ends={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},coords={x=0.476,y=0.51,source="quest_giver",zoneID=15969},questType="standard"},
[96717] = {id=96717,name="Showdown on Naigtal",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16943,description="Now this is quite a strange world, isn't it? The Hal'hadar must have found something of note. The stench of forges indicates they are plundering the riches and resources this remote rock has to offer. If you can disrupt the operations here, you can buy your precious world a moment of respite. Do what you do best, my little monster.",starts={{npcID=263531,x=0.476,y=0.51,mapID=2393},{npcID=265303,x=0.484,y=0.82,zoneID=16943}},ends={{npcID=265303,x=0.484,y=0.82,zoneID=16943}},coords={x=0.476,y=0.51,source="quest_giver",zoneID=15969},questType="standard"},
[96718] = {id=96718,name="Showdown on Naigtal (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16943,description="Now this is quite a strange world, isn't it? The Hal'hadar must have found something of note. The stench of forges indicates they are plundering the riches and resources this remote rock has to offer. If you can disrupt the operations here, you can buy your precious world a moment of respite. Do what you do best, my little monster.",starts={{npcID=263531,x=0.476,y=0.51,mapID=2393},{npcID=265303,x=0.484,y=0.82,zoneID=16943}},ends={{npcID=265303,x=0.484,y=0.82,zoneID=16943}},coords={x=0.476,y=0.51,source="quest_giver",zoneID=15969},questType="standard"},
[96720] = {id=96720,name="Showdown on Naigtal",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="Now this is quite a strange world, isn't it? The Hal'hadar must have found something of note. The stench of forges indicates they are plundering the riches and resources this remote rock has to offer. If you can disrupt the operations here, you can buy your precious world a moment of respite. Do what you do best, my little monster.",starts={{npcID=263531,x=0.476,y=0.51,mapID=2393},{npcID=265303,x=0.484,y=0.82,zoneID=16943}},ends={{npcID=265303,x=0.484,y=0.82,zoneID=16943}},coords={x=0.476,y=0.51,source="quest_giver",zoneID=15969},questType="standard"},
[96727] = {id=96727,name="Midnight: Offworld Showdowns",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=17103,description="Our effort to thwart the Void Assaults in Eversong and Zul'Aman have seen much success, but if we do not find a way to stop our aggressors from coming to our lands, they will bleed us until we can no longer stand. Riftblade Maella has recently discovered the location of two of our enemies' bases. She seeks to take the fight to them. Will you aid her strike team? Your efforts will not go unnoticed in these dark times!",ends={{npcID=256203,x=0.49,y=0.646,mapID=2393}},questType="standard"},
[96728] = {id=96728,name="Ritual Site Studies: Week 1 of 3",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15968,mapID=2395,description="After you reported thinning out their ranks I got to thinking. What do they use to recruit members? Are they just as fanatical as their leaders? I wonder if we can break their will to fight by destroying a greater number of their ranks. I fear it will take more than one example to know for sure.",starts={{npcID=257416,x=0.478,y=0.496,mapID=2393},{npcID=267813,x=0.296,y=0.778,mapID=2437},{npcID=267813,x=0.376,y=0.652,mapID=2395}},ends={{npcID=257416,x=0.478,y=0.496,mapID=2393}},coords={x=0.478,y=0.496,source="quest_giver",mapID=2395},questType="standard"},
[96729] = {id=96729,name="Ritual Site Studies: Week 2 of 3",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I have your next assignment, . I need you to study the resilience of these malevolent boons and their dark obelisks. They focus magic so well and the variety of boons is interesting. I need more data though. When you disrupt the next ritual site I need you to do so with these malevolent boons present.",starts={{npcID=257416,x=0.478,y=0.496,mapID=2393}},ends={{npcID=257416,x=0.478,y=0.496,mapID=2393}},coords={x=0.478,y=0.496,source="quest_giver",mapID=2393},questType="standard"},
[96730] = {id=96730,name="Ritual Site Studies: Week 3 of 3",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15968,mapID=2395,description="I think I am on the brink of a big discovery. These latest rituals involve a magic I had not previously heard of in the form of powerful embers that use the energy of their own forces to bolster their leader. If you disrupt these rituals and report your findings to me, I might be able to put this magic to use for us. Do not look at me that way. On my own demon minions of course. Did you think I meant troops like you? We are much too early for trials like that. Report back with your findings!",starts={{npcID=257416,x=0.478,y=0.496,mapID=2393},{npcID=267813,x=0.296,y=0.778,mapID=2437},{npcID=267813,x=0.376,y=0.652,mapID=2395}},ends={{npcID=257416,x=0.478,y=0.496,mapID=2393}},coords={x=0.478,y=0.496,source="quest_giver",mapID=2395},questType="standard"},
[96731] = {id=96731,name="Advanced Ritual Site Studies: Week 4 of 6",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="I had an idea right after you left. We have thinned out their ranks, we have also seen that they can summon additional reinforcements. I want to test the limits of their reserves. If you take on this set of challenges, I promise you another key for the vault.",starts={{npcID=257416,x=0.478,y=0.496,mapID=2393}},ends={{npcID=257416,x=0.478,y=0.496,mapID=2393}},coords={x=0.478,y=0.496,source="quest_giver",mapID=2393},questType="standard"},
[96732] = {id=96732,name="Advanced Ritual Site Studies: Week 5 of 6",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Now that we have tested their troop reserves, our focus will be the dark obelisks and these boons they give. This requires close scrutiny and will surely entail you facing increased patrols while you explore the site. Not too difficult for someone like yourself. Just avoid them... or deal with them if you must.",starts={{npcID=257416,x=0.478,y=0.496,mapID=2393}},ends={{npcID=257416,x=0.478,y=0.496,mapID=2393}},coords={x=0.478,y=0.496,source="quest_giver",mapID=2393},questType="standard"},
[96733] = {id=96733,name="Advanced Ritual Site Studies: Week 6 of 6",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Welcome back my star pupil. I have one last assignment for you and this one will be a challenge. These embers that they use in these rituals. I have not had any success in replicating them or finding a way to counter them. I have one last idea I want you to try. You reported seeing magical manifestations of caster spirits. I have a theory that with these two challenges present there might be a way for them to cancel each other out.",starts={{npcID=257416,x=0.478,y=0.496,mapID=2393}},ends={{npcID=257416,x=0.478,y=0.496,mapID=2393}},coords={x=0.478,y=0.496,source="quest_giver",mapID=2393},questType="standard"},
[96744] = {id=96744,name="Bouncy Mushrooms",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="Hello! Here's a trick to help you bounce on the purple mushrooms around here. You'll need it, because... I want some canopy specimens from the sporerays above us. Bounce up there, get some specimens, then come back down and I'll teach you how to ALWAYS bounce on those mushrooms.",starts={{npcID=265559,x=0.478,y=0.812,zoneID=16943}},ends={{npcID=265559,x=0.478,y=0.812,zoneID=16943}},coords={x=0.478,y=0.812,source="quest_giver",zoneID=16943},questType="standard"},
[96745] = {id=96745,name="Aerospores",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="Now, practice using aerospores . They're up there too if you know where to look. Use them to shoot through the air! You'll need to bounce on mushrooms to get up to the spores and see them. Once you're up there, pass through some aerospores and find out what they do!",starts={{npcID=265559,x=0.478,y=0.812,zoneID=16943}},ends={{npcID=265559,x=0.478,y=0.812,zoneID=16943}},coords={x=0.478,y=0.812,source="quest_giver",zoneID=16943},questType="standard"},
[96780] = {id=96780,name="Local Kafa Shop",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=16105,mapID=2352,starts={{npcID=263258,x=0.552,y=0.618,mapID=2351},{npcID=263258,x=0.55,y=0.434,mapID=2352}},ends={{npcID=263258,x=0.552,y=0.618,mapID=2351},{npcID=263258,x=0.55,y=0.434,mapID=2352}},coords={x=0.552,y=0.618,source="quest_giver",mapID=2352},questType="standard"},
[96794] = {id=96794,name="Fury of the Dead",level=90,requiredLevel=90,faction="none",expansion=11,questType="standard"},
[96801] = {id=96801,name="Calling All Combatants!",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Run, don't walk! The Artisan's Consortium has teamed up with local Silvermoon artisans in Falconwing Square to offer a new selection of heraldries and crafted equipment. These are certified for use in arenas and battlegrounds, guaranteed! Head on down and look for Mirvedon to receive your free sample today. Act now while supplies last! Terms and conditions apply. -Aisha",ends={{npcID=243225,x=0.34,y=0.812,mapID=2393}},questType="standard"},
[96831] = {id=96831,name="Magister's Summons",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=17067,description="Magister Umbric sends word that he and Rommath have a lead to further your empowerment of the Omnium Folio.",starts={{npcID=265903,x=0.478,y=0.516,mapID=2393}},ends={{npcID=264069,x=0.604,y=0.112,zoneID=17067}},coords={x=0.478,y=0.516,source="quest_giver",zoneID=15969},questType="standard"},
[96845] = {id=96845,name="The Grappler",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="You have to try this Lightforge Hookshot ! Here, take this loaner one. To learn the ropes, use it on some mushrooms and aerospores around here. Come back and I'll give you a Hookshot for keeps.",starts={{npcID=265581,x=0.634,y=0.21,zoneID=16900},{npcID=265581,x=0.48,y=0.832,zoneID=16943}},ends={{npcID=265581,x=0.634,y=0.21,zoneID=16900},{npcID=265581,x=0.48,y=0.832,zoneID=16943}},coords={x=0.634,y=0.21,source="quest_giver",zoneID=16900},questType="standard"},
[96935] = {id=96935,name="Curse Surge",level=90,requiredLevel=90,faction="none",expansion=11,questType="standard"},
[97026] = {id=97026,name="Esoteric Ingredients",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,ends={{npcID=254599,x=0.574,y=0.486,zoneID=16365}},questType="standard"},
[97034] = {id=97034,name="Vanquish the Warmonger",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="Poor Impotus doesn't seem to believe we can seize control from his nefarious kin. He's tragically unimaginative. We'll just need to show him an example of our combined strength. Slay that brute of a newcomer, Ignedus. I think his armor would look nice on our new savior. Ignedus seems to be quite careful in showing his face, but clearly quick to anger. Get in there and make some noise, as you're so comfortable doing. I expect him to respond in kind.",starts={{npcID=264879,x=0.598,y=0.218,zoneID=16900}},ends={{npcID=264941,x=0.62,y=0.216,zoneID=16900}},coords={x=0.598,y=0.218,source="quest_giver",zoneID=16900},questType="standard"},
[97035] = {id=97035,name="Depose the Deranged",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="Defeating Ignedus is impressive, I suppose, but it does not mean you're any closer to taking Val. Periculus won't let you meddle with his playthings. He is an... eccentric one, to say the least, and dreadfully fascinated by you flesh-beings. You'll likely find him in the darkest hole this world has to offer, carving open the livestock that Pertinax gathered. He likes to toy with his prey, so I would advise caution.",starts={{npcID=264941,x=0.62,y=0.216,zoneID=16900},{npcID=267578,x=0.62,y=0.216,zoneID=16900}},ends={{npcID=267578,x=0.62,y=0.216,zoneID=16900}},coords={x=0.62,y=0.216,source="quest_giver",zoneID=16900},questType="standard"},
[97036] = {id=97036,name="Umbral Title Bout",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="Well then, it seems our goals are more aligned than before. You've impressed me. With Ignedus and Periculus dealt with, all that remains is my former associate. You will find Gladius Reginax atop that high platform, observing her quarry. She already knows you're coming, so don't aim to surprise her. There's only one way up there for you anyway: through that portal in the Glacial Reservoir. I will play my part and join you. A symbol of our... collaboration.",starts={{npcID=267578,x=0.62,y=0.216,zoneID=16900}},ends={{npcID=264879,x=0.598,y=0.218,zoneID=16900}},coords={x=0.62,y=0.216,source="quest_giver",zoneID=16900},questType="standard"},
[97037] = {id=97037,name="Stargrim Revelations",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=15458,mapID=2405,description="We have a problem, . The hologem you found revealed much about our people's time on this world and who the vigilants were in life. Who they were is not the problem, but rather the possessions they carried within their chassis. Possessions now in the hands of the Soul Architect who, as far as my scouts can tell, has left Naigtal. Archmage Y'mera will explain in greater detail.",starts={{npcID=265950,x=0.476,y=0.82,zoneID=16943}},ends={{npcID=245240,x=0.508,y=0.686,mapID=2405}},coords={x=0.476,y=0.82,source="quest_giver",mapID=2405},questType="standard"},
[97071] = {id=97071,name="A Frigid Welcome to Val",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="Even with the element of surprise, we are at a disadvantage without allies. Storming Pertinax's stronghold alone would be a death sentence. Take this beacon Tala'saan gave us and return to our entry point. I will meet you there and deliver my report to Maella. Let us hope we have some sort of shelter awaiting us.",starts={{npcID=263987,x=0.416,y=0.846,zoneID=16900}},ends={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},coords={x=0.416,y=0.846,source="quest_giver",zoneID=16900},questType="standard"},
[97072] = {id=97072,name="A Swampy Welcome to Naigtal",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="The Nexus-Captain is just over that hill, unaware of our arrival. Attacking now would catch his army off guard... and likely result in our demise. No matter what, we will need allies if we are to succeed. Use this beacon to return to our invasion point. By now, Y'mera has likely brought in the rest of our forces to support us. Speak with Maella when you arrive.",starts={{npcID=264028,x=0.708,y=0.622,zoneID=16943}},ends={{npcID=264024,x=0.484,y=0.82,zoneID=16943}},coords={x=0.708,y=0.622,source="quest_giver",zoneID=16943},questType="standard"},
[97073] = {id=97073,name="Rustbolt Retailer",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=16105,mapID=2352,starts={{npcID=267856,x=0.53,y=0.544,mapID=2351},{npcID=267856,x=0.55,y=0.434,mapID=2352}},ends={{npcID=267856,x=0.53,y=0.544,mapID=2351},{npcID=267856,x=0.55,y=0.434,mapID=2352}},coords={x=0.53,y=0.544,source="quest_giver",mapID=2352},questType="standard"},
[97075] = {id=97075,name="Quality Goods",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=16105,mapID=2352,starts={{npcID=267870,x=0.402,y=0.73,mapID=2351},{npcID=267870,x=0.624,y=0.792,mapID=2352}},ends={{npcID=267870,x=0.402,y=0.73,mapID=2351},{npcID=267870,x=0.624,y=0.792,mapID=2352}},coords={x=0.402,y=0.73,source="quest_giver",mapID=2352},questType="standard"},
[97077] = {id=97077,name="A Shot at the Dark",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="Now that our trap is attuned, we just need to lure our prey out into the open. I have strategically... dismantled... certain parts of the projection device I obtained. Impotus should have difficulty seeing and hearing you clearly. Claim to be one of his allies and demand a meeting at once. We will hope his curiosity gets the better of him. And then...",starts={{npcID=267877,x=0.589,y=0.695,zoneID=16900}},ends={{npcID=264879,x=0.598,y=0.218,zoneID=16900}},coords={x=0.589,y=0.695,source="quest_giver",zoneID=16900},questType="standard"},
[97080] = {id=97080,name="More Disruptions: Val",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="We must not let up the pressure. Even now they are rebuilding from our attacks. Venture out again and show them no mercy!",ends={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},questType="standard"},
[97081] = {id=97081,name="More Disruptions: Val (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16900,description="We must not let up the pressure. Even now they are rebuilding from our attacks. Venture out again and again show them no mercy!",ends={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},questType="standard"},
[97082] = {id=97082,name="Dangerous Enemies: Val",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16900,description="Our scouts have reported seeing dangerous elite creatures that are hampering our efforts. I need you to dispatch them so we can continue our primary objective.",ends={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},questType="standard"},
[97083] = {id=97083,name="Dangerous Enemies: Val (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16900,description="Our scouts have reported seeing dangerous elite creatures that are hampering our efforts. I need you to dispatch them so we can continue our primary objective.",ends={{npcID=263482,x=0.596,y=0.218,zoneID=16900}},questType="standard"},
[97084] = {id=97084,name="More Disruption: Naigtal",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="The stench of their forges still lingers. This means they are rebuilding. You must keep at it if you hope to disrupt their operations enough to end their threat. Now you can go. Wreak havoc.",ends={{npcID=264024,x=0.484,y=0.82,zoneID=16943}},questType="standard"},
[97085] = {id=97085,name="Dangerous Enemies: Naigtal",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16943,description="I hear your scouts talk of dangerous creatures and foes they have faced. It makes me wonder if you could defeat them? Why don't you go and try? It will certainly help your efforts here. I hope to see you return mostly intact.",ends={{npcID=264024,x=0.484,y=0.82,zoneID=16943}},questType="standard"},
[97086] = {id=97086,name="Dangerous Enemies: Naigtal (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16943,description="I hear your scouts talk of dangerous creatures and foes they have faced. It makes me wonder if you could defeat them? Why don't you go and try? It will certainly help your efforts here. I hope to see you return mostly intact.",ends={{npcID=264024,x=0.484,y=0.82,zoneID=16943}},questType="standard"},
[97087] = {id=97087,name="More Disruption: Naigtal (Heroic)",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16943,description="The stench of their forges still lingers. This means they are rebuilding. You must keep at it if you hope to disrupt their operations enough to end their threat. Now you can go. Wreak havoc.",ends={{npcID=264024,x=0.484,y=0.82,zoneID=16943}},questType="standard"},
[97141] = {id=97141,name="Spoils of the Vaults",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="It takes de whole of our strength to keep de forces of Ula'tek from overwhelming de isle. Dat battle is waged inside the Vault of Ula'tek, against the endless tide of her children. Kill one, and two more will slither out of de venom. Venture in, , and lend your power to our weary fighters. Who knows? You may even find something valuable in dat ancient, cursed place.",starts={{npcID=268228,x=0.588,y=0.46,zoneID=16365}},ends={{npcID=268228,x=0.588,y=0.46,zoneID=16365}},coords={x=0.588,y=0.46,source="quest_giver",zoneID=16365},questType="standard"},
[97455] = {id=97455,name="Call of the Bell",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,questType="standard"},
[97457] = {id=97457,name="Fits Like a Glove",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},questType="standard"},
[97458] = {id=97458,name="Tackled and Boxed",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},questType="standard"},
[97459] = {id=97459,name="Something Smelly",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},questType="standard"},
[97460] = {id=97460,name="Lightly Salted",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,questType="standard"},
