[97464] = {id=97464,name="A Dash of Poison",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},questType="standard"},
[97465] = {id=97465,name="The Intended Way to Fish",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},questType="standard"},
[97557] = {id=97557,name="Tailing the Tlhapi",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Toxic Tlhapi . Nasty little fish. Everything's wrong about them, from their big, buggy eyes to their sweet, succulent meat... Not to mention the toxicity. The seas would be much better without them fouling things up.",starts={{npcID=268394,x=0.516,y=0.502,zoneID=16365}},ends={{npcID=268394,x=0.516,y=0.502,zoneID=16365}},coords={x=0.516,y=0.502,source="quest_giver",zoneID=16365},questType="standard"},
[97562] = {id=97562,name="Culling the Killifish",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Spotted Killifish . Grotesque little creatures. The little demons swarm like insects, washing up on shores in such horrific numbers that it would take several meals to devour them all. You can do your part by collecting some for me, ridding the waters of their foul presence.",starts={{npcID=268394,x=0.516,y=0.502,zoneID=16365}},ends={{npcID=268394,x=0.516,y=0.502,zoneID=16365}},coords={x=0.516,y=0.502,source="quest_giver",zoneID=16365},questType="standard"},
[97571] = {id=97571,name="Dogging the Darters",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Dirty Darters . Ghoulish little buggers. The way they flit about the water is so unnerving, so disquieting, one can't help but imagine them darting right down one's gullet... You can do your part by collecting some for me, ridding the waters of their foul presence.",starts={{npcID=268394,x=0.516,y=0.502,zoneID=16365}},ends={{npcID=268394,x=0.516,y=0.502,zoneID=16365}},coords={x=0.516,y=0.502,source="quest_giver",zoneID=16365},questType="standard"},
[97616] = {id=97616,name="Corrosive Gifts: Corrosive Power",level=80,requiredLevel=80,faction="both",expansion=11,zoneID=16535,ends={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},questType="standard"},
[97621] = {id=97621,name="The Singularity Anchor",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15458,mapID=2405,description="Our sojourn to this world has brought the ren'dorei an even deeper understanding of the Void than before. The domanaar with whom we share a common enemy are almost strangely generous with their knowledge. I believe they want us to become as fearsome as they are. There is a Singularity Anchor in Stormarion Citadel. I have learned how to draw upon some of its power to craft you a powerful item. But first, we must ensure it does not fall into the hands of our enemies.",starts={{npcID=248328,x=0.526,y=0.728,mapID=2405}},ends={{npcID=248328,x=0.526,y=0.728,mapID=2405}},coords={x=0.526,y=0.728,source="quest_giver",mapID=2405},questType="standard"},
[97622] = {id=97622,name="A Soiree to Remember",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15968,mapID=2395,description="You seek an audience with Saltheril? And you're wearing... that? Excuse me for a moment while I laugh into my handkerchief. Now, let me be professional. You are cordially invited to attend Saltheril's soiree. Don't embarrass yourself, . The best of Silvermoon are watching.",starts={{npcID=240838,x=0.434,y=0.474,mapID=2395}},ends={{npcID=240838,x=0.434,y=0.474,mapID=2395}},coords={x=0.434,y=0.474,source="quest_giver",mapID=2395},questType="standard"},
[97624] = {id=97624,name="Seeking Legends",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15355,mapID=2413,description="Harandar hides wisdom in every annal of its history, . You would do well to seek out its legends for yourself. I suspect you may learn something of this world and our places in it.",starts={{npcID=240407,x=0.51,y=0.508,mapID=2413}},ends={{npcID=240407,x=0.51,y=0.508,mapID=2413}},coords={x=0.51,y=0.508,source="quest_giver",mapID=2413},questType="standard"},
[97625] = {id=97625,name="Glorious Abundance",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description="De Loa of Abundance may not be one of de four great ones, but his worshippers are certainly de most devout. Seek him out yaself. You can find him in northern Zul'Aman near Halazzi's Temple, but I also hear he's established harvest sites in Eversong Woods, Harandar, and even de land of Void through de gargantuan skymouth. If nothing else, de rewards he grants are glorious--to de worthy, at least.",starts={{npcID=240279,x=0.458,y=0.658,mapID=2437}},ends={{npcID=240279,x=0.458,y=0.658,mapID=2437}},coords={x=0.458,y=0.658,source="quest_giver",mapID=2437},questType="standard"},
[97640] = {id=97640,name="Vaults of Atal'Utek: One Coin Too Many",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,description="You don't look so good, . You found something out dere, huh? De vaults are full of treasure, most of it cursed. I don't trust her, but dat spirit-witch you saw knows all de secrets of dis horrid place. If anyone can help, it's her.",starts={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},ends={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},coords={x=0.472,y=0.608,source="quest_giver",zoneID=16535},questType="standard"},
[97661] = {id=97661,name="The Protection of the Med'jai",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,description="Er'inye would likely be interested in studying it.>",ends={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},questType="standard"},
[97662] = {id=97662,name="The Winds of Tok'jara",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,description="Er'inye might be interested in studying it.>",ends={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},questType="standard"},
[97668] = {id=97668,name="The Watchful Gaze of Szarith",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,description="Er'inye would be interested in studying it.>",ends={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},questType="standard"},
[97669] = {id=97669,name="The Luck of the Bound Spirit",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,description="Er'inye would likely be interested in studying it.>",ends={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},questType="standard"},
[97670] = {id=97670,name="A Handful of Voidlight Marl",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,starts={{npcID=268228,x=0.588,y=0.46,zoneID=16365}},ends={{npcID=268228,x=0.588,y=0.46,zoneID=16365}},coords={x=0.588,y=0.46,source="quest_giver",zoneID=16365},questType="standard"},
[97910] = {id=97910,name="Cracked Keystone",level=80,requiredLevel=80,faction="none",expansion=11,description="Fragmentary images of heroic deeds flash through your mind as you touch the stone, but they fade as fast as they arrive. Perhaps performing a suitably impressive task will stabilize the stone's magic once more?",questType="standard"},
[97978] = {id=97978,name="Prismatic Potential",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Greetings, . Our mutual friend explained everything to us. Don't worry, my shade and I took to Decimus' voidweaving like fish to water. We had an idea. The Catalyst's transformative energies are immense and span the breadth of known elemental forces. If I can learn to isolate the void from that spectrum of power, I could use it to weave Nebulous Voidcores just as Decimus did with the Voidforge. We are no domanaar, though. We need practice.",starts={{npcID=269987,x=0.4,y=0.646,mapID=2393}},ends={{npcID=269987,x=0.4,y=0.646,mapID=2393}},coords={x=0.4,y=0.646,source="quest_giver",mapID=2393},questType="standard"},
[98172] = {id=98172,name="Trailing Xal'atath",level=90,requiredLevel=90,faction="alliance",expansion=11,zoneID=15969,mapID=2393,description="We must not lose sight of our true goal here in Silvermoon, : to bring Xal'atath to justice. We all saw her void armies at the Sunwell. They were rushing downward, INTO the well, a thousand a minute. And now: silence. Listen for their whispers, . With any luck, we'll pick up on their trail again, and then we'll find Xal'atath... and perhaps even those that pursued her.",starts={{npcID=270645,x=0.49,y=0.646,mapID=2393}},ends={{npcID=270645,x=0.49,y=0.646,mapID=2393}},coords={x=0.49,y=0.646,source="quest_giver",mapID=2393},questType="standard"},
[98204] = {id=98204,name="Cursed Keepsake",level=0,requiredLevel=0,faction="both",expansion=11,questType="standard"},
[98218] = {id=98218,name="Return to Amani'Zar",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15947,mapID=2437,description=", Your aid is requested in Amani'Zar Village. Please meet me there. --Liadrin",ends={{npcID=263331,x=0.436,y=0.682,mapID=2437}},questType="standard"},
[98232] = {id=98232,name="Midnight: Vaults of Atal'Utek",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Zul'jarra's forces stand watch at the gates of the Vaults of Atal'Utek, holding the line against those wicked serpents. The fate of the entire Eastern Kingdoms rests on their blades. We would do well to provide them with reinforcements. The Children of Ula'tek are fierce, but they are no match for a seasoned like you. Traverse the temple and thin their ranks, however you can.",ends={{npcID=256203,x=0.49,y=0.646,mapID=2393}},questType="standard"},
[98234] = {id=98234,name="Week 1 of 3: Gladiator's Distinction",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=15969,mapID=2393,description="Interested in training against some of our fighters? Step into the ring and show us your mettle. Make sure you equip these medallions, and defeat at least two teams of enemies.",starts={{npcID=256212,x=0.488,y=0.646,mapID=2393}},ends={{npcID=256212,x=0.488,y=0.646,mapID=2393}},coords={x=0.488,y=0.646,source="quest_giver",mapID=2393},questType="pvp"},
[98343] = {id=98343,name="Venom Fishing: My Second-Best",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Before I send ye out hunting, ye should acquaint yerself with what remains of my crew. Most perished in the wreck, of course. Others fell into the swamp. Some traitorous gits... well, we'll get to them in a moment, won't we? But me loyal second mate is holding down the fort, just down river of me Landing. She'll set you up right.",starts={{npcID=258755,x=0.572,y=0.486,zoneID=16365}},ends={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},coords={x=0.572,y=0.486,source="quest_giver",zoneID=16365},questType="standard"},
[98388] = {id=98388,name="Into the Vaults of Atal'Utek",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,description="Past dis bulwark, there's nothin but snakes, spirits, and venomous death. I've lost three lieutenants dis week. Strong ones. Brave ones. Maybe stronger and braver than you. Warleader Abdumati looks you over with a weary eye.> If you want to fling yaself into de abyss, be my guest. Bring back my scouts, if you can find dem amongst de bones. But watch your step. Dat venom will swallow you whole.",starts={{npcID=262798,x=0.472,y=0.608,zoneID=16535},{npcID=271885,x=0.54,y=0.396,zoneID=16535}},ends={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},coords={x=0.472,y=0.608,source="quest_giver",zoneID=16535},questType="standard"},
[98406] = {id=98406,name="A Curated Gift",level=0,requiredLevel=0,faction="both",expansion=11,zoneID=15524,mapID=2351,description="I have watched the effort and care you take with the other mortals of your neighborhood, here in Razorwind Shores. This ceaseless labor on their behalf is the sort of behavior that I encourage. There's no profit to be had for you, but that isn't a driving concern for the best of your kind. In recognition of your efforts and status, I offer you a gift. This small device contains a piece of decor for you to place in your home. I will have another for you next week.",ends={{npcID=248854,x=0.526,y=0.374,mapID=2352},{npcID=253596,x=0.536,y=0.574,mapID=2351}},questType="standard"},
[98414] = {id=98414,name="A Request from the Captain",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Oh, uh. The Captain has requested you join him at Tokka's Landing as soon as you can. Second Mate Sluggs quivers in her shell.> He had a mean look about him. Tread lightly.",starts={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},ends={{npcID=258755,x=0.572,y=0.486,zoneID=16365}},coords={x=0.516,y=0.498,source="quest_giver",zoneID=16365},questType="standard"},
[98415] = {id=98415,name="A Favor to the Captain",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16365,description="Oh! While you were out fishing, Captain Tokka asked to see you again. I think he's beginning to trust you. Second Mate Sluggs grimaces.> The Captain's trust d-does tend to come with caveats.",starts={{npcID=257598,x=0.516,y=0.498,zoneID=16365}},ends={{npcID=258755,x=0.572,y=0.486,zoneID=16365}},coords={x=0.516,y=0.498,source="quest_giver",zoneID=16365},questType="standard"},
[98416] = {id=98416,name="A Plea from the Captain",level=90,requiredLevel=90,faction="none",expansion=11,zoneID=16365,description="Ohh, the Captain's really in a foul mood this time. I think you'd better go see what he wants. You're the only one who can soothe his storms, these days.",questType="standard"},
[98428] = {id=98428,name="Vaults of Atal'Utek: The Altar of Corrosion",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,description="De Altar of Corrosion . Who can say when dis accursed piece of stone rose out of de venom? I have studied it for lifetimes and have only just tasted its power. Er'inye licks her spectral lips.> Say de word, and I will convert de corrosion you carry to something more useful. Den, you may commune with de Altar and accept its many gifts.",starts={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},ends={{npcID=262880,x=0.51,y=0.626,zoneID=16535}},coords={x=0.51,y=0.626,source="quest_giver",zoneID=16535},questType="standard"},
[98515] = {id=98515,name="Vaults of Atal'Utek: A Toxic Tour",level=90,requiredLevel=90,faction="both",expansion=11,zoneID=16535,description="Dis temple is where all de Children of Ula'tek first crawl out of de ooze. Dis is where we hold de line. De threat comes in waves. Sometimes short strikes. Sometimes an incursion dat overwhelms de whole temple. Sometimes a huge monstrosity rising out of de venom. Whatever dey send, send it back cryin' to its big evil mama! And in de meantime, do what you can to keep our patrols safe.",starts={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},ends={{npcID=262798,x=0.472,y=0.608,zoneID=16535}},coords={x=0.472,y=0.608,source="quest_giver",zoneID=16535},questType="standard"},
}
end)
